const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/components/admin/AdminTable.tsx":"\"use client\";\nimport { ReactNode } from \"react\";\n\nconst t = {\n  border: \"rgba(255,255,255,0.07)\",\n  text:   \"rgba(255,255,255,0.9)\",\n  muted:  \"rgba(255,255,255,0.4)\",\n  card:   \"rgba(255,255,255,0.03)\",\n};\n\nexport function StatGrid({ children, cols=4 }: { children:ReactNode; cols?:number }) {\n  return (\n    <>\n      <div style={{ display:\"grid\", gridTemplateColumns:`repeat(${cols},1fr)`, gap:12, marginBottom:20 }} className=\"adm-stat-grid\">\n        {children}\n      </div>\n      <style>{`@media(max-width:900px){ .adm-stat-grid{ grid-template-columns:1fr 1fr!important; } } @media(max-width:480px){ .adm-stat-grid{ gap:8px!important; } }`}</style>\n    </>\n  );\n}\n\nexport function StatCard({ label, value, color, icon:Icon, sub }: any) {\n  return (\n    <div style={{ padding:18, borderRadius:16, background:t.card, border:`1px solid ${t.border}` }}>\n      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:14 }}>\n        <div style={{ width:34, height:34, borderRadius:10, background:`${color}14`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n          <Icon size={15} color={color}/>\n        </div>\n        {sub !== undefined && (\n          <span style={{ fontSize:10, fontWeight:700, padding:\"2px 8px\", borderRadius:99, background:sub>=0?\"rgba(16,185,129,0.1)\":\"rgba(239,68,68,0.1)\", color:sub>=0?\"#10B981\":\"#EF4444\" }}>\n            {sub>=0?\"+\":\"\"}{sub}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize:22, fontWeight:900, color:t.text, letterSpacing:\"-0.05em\", margin:\"0 0 3px\", lineHeight:1 }}>{value}</p>\n      <p style={{ fontSize:11, color:t.muted, margin:0 }}>{label}</p>\n    </div>\n  );\n}\n\nexport function Badge({ label, color, bg }: { label:string; color:string; bg:string }) {\n  return (\n    <span style={{ fontSize:11, fontWeight:700, padding:\"3px 10px\", borderRadius:99, background:bg, color, display:\"inline-block\", whiteSpace:\"nowrap\" }}>\n      {label}\n    </span>\n  );\n}\n\nexport function FilterBar({ children }: { children:ReactNode }) {\n  return (\n    <>\n      <div style={{ display:\"flex\", gap:10, marginBottom:14, flexWrap:\"wrap\" }} className=\"adm-filter\">\n        {children}\n      </div>\n      <style>{`@media(max-width:640px){ .adm-filter>div,.adm-filter>select,.adm-filter>input{ width:100%!important; flex:none!important; } }`}</style>\n    </>\n  );\n}\n\nexport function SearchInput({ value, onChange, placeholder }: { value:string; onChange:(v:string)=>void; placeholder?:string }) {\n  return (\n    <div style={{ flex:1, minWidth:200, display:\"flex\", alignItems:\"center\", gap:8, padding:\"9px 14px\", borderRadius:12, background:\"rgba(255,255,255,0.04)\", border:`1px solid ${t.border}` }}>\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"rgba(255,255,255,0.4)\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.35-4.35\"/></svg>\n      <input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder||\"Search...\"}\n        style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", color:t.text, fontSize:13, fontFamily:\"inherit\" }}/>\n    </div>\n  );\n}\n\nexport function SelectFilter({ value, onChange, options }: { value:string; onChange:(v:string)=>void; options:{value:string;label:string}[] }) {\n  return (\n    <select value={value} onChange={e => onChange(e.target.value)}\n      style={{ padding:\"9px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:\"rgba(255,255,255,0.04)\", color:\"rgba(255,255,255,0.6)\", fontSize:13, fontFamily:\"inherit\", outline:\"none\", cursor:\"pointer\" }}>\n      {options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}\n    </select>\n  );\n}\n\nexport function PageHeader({ title, sub, action }: { title:string; sub:string; action?:ReactNode }) {\n  return (\n    <div style={{ display:\"flex\", alignItems:\"flex-start\", justifyContent:\"space-between\", marginBottom:22, gap:12, flexWrap:\"wrap\" }}>\n      <div>\n        <h1 style={{ fontSize:\"clamp(18px,3vw,24px)\", fontWeight:900, letterSpacing:\"-0.04em\", color:t.text, margin:\"0 0 3px\" }}>{title}</h1>\n        <p style={{ fontSize:13, color:t.muted, margin:0 }}>{sub}</p>\n      </div>\n      {action && <div>{action}</div>}\n    </div>\n  );\n}\n\nexport function Pagination({ page, pages, total, onPage }: { page:number; pages:number; total:number; onPage:(p:number)=>void }) {\n  if (!pages || pages <= 1) return null;\n  const range = Array.from({ length: Math.min(pages, 5) }, (_, i) => {\n    if (pages <= 5) return i + 1;\n    if (page <= 3) return i + 1;\n    if (page >= pages - 2) return pages - 4 + i;\n    return page - 2 + i;\n  }).filter(p => p >= 1 && p <= pages);\n  const btn = (active: boolean): any => ({ minWidth:32, height:32, padding:\"0 10px\", borderRadius:8, border:`1px solid ${active?\"rgba(107,53,232,0.5)\":\"rgba(255,255,255,0.07)\"}`, background:active?\"rgba(107,53,232,0.15)\":\"transparent\", color:active?\"#A78BFA\":\"rgba(255,255,255,0.4)\", cursor:\"pointer\", fontSize:12, fontWeight:active?700:400 });\n  return (\n    <div style={{ display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\", marginTop:14, flexWrap:\"wrap\", gap:10 }}>\n      <span style={{ fontSize:12, color:\"rgba(255,255,255,0.3)\" }}>{(total||0).toLocaleString()} total</span>\n      <div style={{ display:\"flex\", gap:4, flexWrap:\"wrap\" }}>\n        <button onClick={() => onPage(page-1)} disabled={page===1} style={{ ...btn(false), opacity:page===1?0.3:1 }}>←</button>\n        {range.map(p => <button key={p} onClick={() => onPage(p)} style={btn(p===page)}>{p}</button>)}\n        <button onClick={() => onPage(page+1)} disabled={page>=pages} style={{ ...btn(false), opacity:page>=pages?0.3:1 }}>→</button>\n      </div>\n    </div>\n  );\n}\n\nexport function DataTable({ cols, rows, loading, empty=\"No records found\" }: {\n  cols: { key:string; label:string; width?:string; hide?:\"sm\"|\"md\" }[];\n  rows: { [key:string]:ReactNode }[];\n  loading?: boolean;\n  empty?:   string;\n}) {\n  const tplCols = cols.map(c => c.width || \"1fr\").join(\" \");\n  return (\n    <div style={{ borderRadius:16, border:`1px solid ${t.border}`, overflow:\"hidden\", overflowX:\"auto\" }}>\n      <div style={{ minWidth:480 }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:tplCols, gap:0, padding:\"9px 16px\", background:\"rgba(255,255,255,0.02)\", borderBottom:`1px solid ${t.border}` }}>\n          {cols.map(c => (\n            <span key={c.key} className={c.hide?`adm-col-hide-${c.hide}`:\"\"} style={{ fontSize:10, fontWeight:700, letterSpacing:\"0.08em\", color:\"rgba(255,255,255,0.25)\", textTransform:\"uppercase\" }}>\n              {c.label}\n            </span>\n          ))}\n        </div>\n        {loading ? (\n          <div style={{ padding:\"40px 0\", textAlign:\"center\", color:t.muted, fontSize:13 }}>Loading...</div>\n        ) : rows.length === 0 ? (\n          <div style={{ padding:\"40px 0\", textAlign:\"center\", color:t.muted, fontSize:13 }}>{empty}</div>\n        ) : rows.map((row, i) => (\n          <div key={i} style={{ display:\"grid\", gridTemplateColumns:tplCols, gap:0, padding:\"12px 16px\", borderBottom:`1px solid rgba(255,255,255,0.04)`, alignItems:\"center\" }}>\n            {cols.map(c => (\n              <div key={c.key} className={c.hide?`adm-col-hide-${c.hide}`:\"\"} style={{ overflow:\"hidden\", minWidth:0 }}>\n                {row[c.key]}\n              </div>\n            ))}\n          </div>\n        ))}\n      </div>\n      <style>{`@media(max-width:768px){ .adm-col-hide-md{display:none!important;} } @media(max-width:540px){ .adm-col-hide-sm{display:none!important;} }`}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/layout.tsx":"\"use client\";\nimport { useEffect, useState } from \"react\";\nimport { useRouter, usePathname } from \"next/navigation\";\nimport Link from \"next/link\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport {\n  LayoutDashboard, Users, Store, ShoppingCart, CreditCard,\n  BarChart2, Settings, AlertCircle, Shield, Bell, LogOut,\n  Menu, X, Globe, Megaphone, Flag, ChevronRight,\n  TrendingDown, TrendingUp, Tag, Mail, Building2,\n} from \"lucide-react\";\n\nconst C = { bg:\"#0A0714\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\", accent:\"#6B35E8\" };\n\nconst NAV = [\n  { section: null, items: [\n    { href:\"/admin\",                 icon:LayoutDashboard, label:\"Overview\",        exact:true },\n  ]},\n  { section:\"PLATFORM\", items: [\n    { href:\"/admin/users\",           icon:Users,           label:\"Users\"           },\n    { href:\"/admin/stores\",          icon:Store,           label:\"Stores\"          },\n    { href:\"/admin/orders\",          icon:ShoppingCart,    label:\"Orders\"          },\n    { href:\"/admin/payments\",        icon:CreditCard,      label:\"Payments\"        },\n    { href:\"/admin/paystack\",        icon:Building2,       label:\"Paystack\"        },\n  ]},\n  { section:\"ANALYTICS\", items: [\n    { href:\"/admin/analytics\",       icon:BarChart2,       label:\"Analytics\"       },\n    { href:\"/admin/growth\",          icon:TrendingUp,      label:\"Growth\"          },\n    { href:\"/admin/churn\",           icon:TrendingDown,    label:\"Churn\"           },\n  ]},\n  { section:\"TOOLS\", items: [\n    { href:\"/admin/broadcast\",       icon:Megaphone,       label:\"Broadcast\"       },\n    { href:\"/admin/coupons\",         icon:Tag,             label:\"Coupons\"         },\n    { href:\"/admin/email-templates\", icon:Mail,            label:\"Email Templates\" },\n    { href:\"/admin/flags\",           icon:Flag,            label:\"Feature Flags\"   },\n    { href:\"/admin/support\",         icon:Bell,            label:\"Support\"         },\n  ]},\n  { section:\"SYSTEM\", items: [\n    { href:\"/admin/audit-logs\",      icon:Shield,          label:\"Audit Logs\"      },\n    { href:\"/admin/error-logs\",      icon:AlertCircle,     label:\"Error Logs\"      },\n    { href:\"/admin/settings\",        icon:Settings,        label:\"Settings\"        },\n  ]},\n];\n\nexport default function AdminLayout({ children }: { children: React.ReactNode }) {\n  const { user, isHydrated, logout } = useAuthStore();\n  const router   = useRouter();\n  const pathname = usePathname();\n  const [mobileOpen, setMobileOpen] = useState(false);\n\n  useEffect(() => {\n    if (!isHydrated) return;\n    if (!user) { router.replace(\"/auth/login\"); return; }\n    if (user.role !== \"SUPER_ADMIN\") router.replace(\"/dashboard\");\n  }, [user, isHydrated]);\n\n  if (!isHydrated || !user || user.role !== \"SUPER_ADMIN\") return (\n    <div style={{ minHeight:\"100vh\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", background:C.bg }}>\n      <div style={{ width:32, height:32, borderRadius:\"50%\", border:`3px solid rgba(107,53,232,0.15)`, borderTopColor:C.accent, animation:\"spin 0.7s linear infinite\" }}/>\n      <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>\n    </div>\n  );\n\n  const isActive = (n: any) => n.exact ? pathname === n.href : pathname.startsWith(n.href);\n\n  const Sidebar = () => (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", overflowY:\"auto\" }}>\n      {/* Logo */}\n      <div style={{ padding:\"18px 14px 14px\", borderBottom:`1px solid ${C.border}`, flexShrink:0 }}>\n        <Link href=\"/admin\" style={{ display:\"flex\", alignItems:\"center\", gap:10, textDecoration:\"none\" }}>\n          <div style={{ width:32, height:32, borderRadius:9, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n            <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n          </div>\n          <div>\n            <p style={{ fontSize:14, fontWeight:900, color:\"#fff\", margin:0, letterSpacing:\"-0.03em\" }}>Drop<span style={{ color:C.accent }}>OS</span></p>\n            <p style={{ fontSize:9, color:\"rgba(255,255,255,0.28)\", margin:0, fontWeight:700, letterSpacing:\"0.1em\" }}>SUPER ADMIN</p>\n          </div>\n        </Link>\n      </div>\n\n      {/* Nav */}\n      <nav style={{ flex:1, padding:\"10px 8px\", overflowY:\"auto\" }}>\n        {NAV.map((group, gi) => (\n          <div key={gi} style={{ marginBottom:6 }}>\n            {group.section && (\n              <p style={{ fontSize:9, fontWeight:800, letterSpacing:\"0.12em\", color:\"rgba(255,255,255,0.18)\", textTransform:\"uppercase\", padding:\"5px 10px 2px\", margin:0 }}>\n                {group.section}\n              </p>\n            )}\n            {group.items.map(n => {\n              const active = isActive(n);\n              const Icon   = n.icon;\n              return (\n                <Link key={n.href} href={n.href} onClick={() => setMobileOpen(false)}\n                  style={{ display:\"flex\", alignItems:\"center\", gap:9, padding:\"7px 10px\", borderRadius:9, marginBottom:1, textDecoration:\"none\", background:active?\"rgba(107,53,232,0.12)\":\"transparent\", border:`1px solid ${active?\"rgba(107,53,232,0.18)\":\"transparent\"}`, transition:\"all 0.12s\" }}>\n                  <Icon size={13} color={active?\"#A78BFA\":\"rgba(255,255,255,0.32)\"}/>\n                  <span style={{ fontSize:12, fontWeight:active?700:500, color:active?\"#fff\":\"rgba(255,255,255,0.45)\", flex:1 }}>{n.label}</span>\n                  {active && <ChevronRight size={10} color=\"rgba(167,139,250,0.5)\"/>}\n                </Link>\n              );\n            })}\n          </div>\n        ))}\n      </nav>\n\n      {/* Footer */}\n      <div style={{ padding:\"10px 10px 14px\", borderTop:`1px solid ${C.border}`, flexShrink:0 }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:8, padding:\"8px 10px\", borderRadius:10, background:\"rgba(255,255,255,0.03)\", marginBottom:8 }}>\n          <div style={{ width:28, height:28, borderRadius:8, background:\"linear-gradient(145deg,#2D1B69,#6B35E8)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:12, fontWeight:900, color:\"#fff\", flexShrink:0 }}>\n            {user.name?.charAt(0)||\"A\"}\n          </div>\n          <div style={{ flex:1, minWidth:0 }}>\n            <p style={{ fontSize:12, fontWeight:700, color:\"rgba(255,255,255,0.8)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{user.name}</p>\n            <p style={{ fontSize:10, color:\"rgba(255,255,255,0.28)\", margin:0 }}>Super Admin</p>\n          </div>\n        </div>\n        <div style={{ display:\"flex\", gap:6 }}>\n          <Link href=\"/dashboard\" style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:4, padding:\"6px\", borderRadius:8, background:\"rgba(255,255,255,0.04)\", border:`1px solid ${C.border}`, textDecoration:\"none\", fontSize:11, fontWeight:600, color:\"rgba(255,255,255,0.4)\" }}>\n            <Globe size={10}/> Store\n          </Link>\n          <button onClick={() => { logout(); router.push(\"/auth/login\"); }}\n            style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:4, padding:\"6px\", borderRadius:8, background:\"rgba(239,68,68,0.07)\", border:\"1px solid rgba(239,68,68,0.12)\", cursor:\"pointer\", fontSize:11, fontWeight:600, color:\"rgba(239,68,68,0.6)\", fontFamily:\"inherit\" }}>\n            <LogOut size={10}/> Out\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n\n  return (\n    <div style={{ minHeight:\"100vh\", background:C.bg, fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\", display:\"flex\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');\n        *{box-sizing:border-box;margin:0;}\n        @keyframes spin{to{transform:rotate(360deg)}}\n        :root{--accent:#6B35E8;--green:#10B981;--amber:#F59E0B;--red:#EF4444;--cyan:#06B6D4;}\n        @media(min-width:1024px){.adm-sidebar{display:flex!important}.adm-topbar{display:none!important}}\n        @media(max-width:1023px){.adm-sidebar{display:none!important}.adm-topbar{display:flex!important}}\n      `}</style>\n\n      {/* Desktop sidebar */}\n      <aside className=\"adm-sidebar\" style={{ width:210, flexShrink:0, background:\"rgba(255,255,255,0.015)\", borderRight:`1px solid ${C.border}`, height:\"100vh\", position:\"sticky\", top:0, flexDirection:\"column\" }}>\n        <Sidebar/>\n      </aside>\n\n      {/* Mobile overlay */}\n      {mobileOpen && (\n        <div style={{ position:\"fixed\", inset:0, zIndex:50, display:\"flex\" }}>\n          <div onClick={() => setMobileOpen(false)} style={{ flex:1, background:\"rgba(0,0,0,0.6)\", backdropFilter:\"blur(4px)\" }}/>\n          <div style={{ width:220, background:\"#0d0a1a\", borderLeft:`1px solid ${C.border}`, height:\"100%\", display:\"flex\", flexDirection:\"column\" }}>\n            <Sidebar/>\n          </div>\n        </div>\n      )}\n\n      {/* Main */}\n      <div style={{ flex:1, display:\"flex\", flexDirection:\"column\", minWidth:0 }}>\n        {/* Mobile topbar */}\n        <div className=\"adm-topbar\" style={{ alignItems:\"center\", justifyContent:\"space-between\", padding:\"12px 16px\", borderBottom:`1px solid ${C.border}`, position:\"sticky\", top:0, background:\"rgba(10,7,20,0.96)\", backdropFilter:\"blur(10px)\", zIndex:30 }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10 }}>\n            <div style={{ width:28, height:28, borderRadius:8, background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/></svg>\n            </div>\n            <span style={{ fontSize:14, fontWeight:900, color:\"#fff\" }}>Admin</span>\n          </div>\n          <button onClick={() => setMobileOpen(o => !o)} style={{ background:\"none\", border:\"none\", cursor:\"pointer\", color:\"rgba(255,255,255,0.5)\", padding:4 }}>\n            {mobileOpen ? <X size={18}/> : <Menu size={18}/>}\n          </button>\n        </div>\n\n        <main style={{ flex:1, padding:\"clamp(16px,2.5vw,28px)\", overflowY:\"auto\" }}>\n          {children}\n        </main>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/admin/page.tsx":"\"use client\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { motion } from \"framer-motion\";\nimport { adminAPI } from \"../../lib/api\";\nimport { AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from \"recharts\";\nimport { Users, DollarSign, ShoppingCart, TrendingUp, Store, Zap, ArrowUpRight, Activity, Clock, ChevronRight, AlertCircle } from \"lucide-react\";\nimport Link from \"next/link\";\n\nconst V = { v500:\"#6B35E8\", v700:\"#3D1C8A\", v400:\"#8B5CF6\", v300:\"#A78BFA\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\n\nfunction fmt(n: number) { return new Intl.NumberFormat(\"en-NG\",{style:\"currency\",currency:\"NGN\",maximumFractionDigits:0}).format(n||0); }\nfunction num(n: number) { return n>=1000000?`${(n/1000000).toFixed(1)}M`:n>=1000?`${(n/1000).toFixed(1)}k`:String(n||0); }\n\nfunction StatCard({ label, value, sub, color, icon:Icon, delay=0 }: any) {\n  return (\n    <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay}}\n      style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:14 }}>\n        <div style={{ width:36, height:36, borderRadius:10, background:`${color}15`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n          <Icon size={16} color={color}/>\n        </div>\n        {sub !== undefined && (\n          <span style={{ fontSize:11, fontWeight:700, color:sub>=0?V.green:V.red, background:sub>=0?\"rgba(16,185,129,0.1)\":\"rgba(239,68,68,0.1)\", padding:\"2px 8px\", borderRadius:99 }}>\n            {sub>=0?\"+\":\"\"}{sub}%\n          </span>\n        )}\n      </div>\n      <p style={{ fontSize:24, fontWeight:900, color:\"#fff\", letterSpacing:\"-0.05em\", margin:\"0 0 4px\", lineHeight:1 }}>{value}</p>\n      <p style={{ fontSize:12, color:\"rgba(255,255,255,0.4)\", margin:0 }}>{label}</p>\n    </motion.div>\n  );\n}\n\nconst DEMO_REVENUE = [\n  {month:\"Jan\",revenue:1840000,fees:184000},{month:\"Feb\",revenue:2360000,fees:236000},\n  {month:\"Mar\",revenue:2890000,fees:289000},{month:\"Apr\",revenue:3520000,fees:352000},\n  {month:\"May\",revenue:4380000,fees:438000},{month:\"Jun\",revenue:5210000,fees:521000},\n  {month:\"Jul\",revenue:6140000,fees:614000},{month:\"Aug\",revenue:7200000,fees:720000},\n];\n\nconst DEMO_GW = [\n  {name:\"Paystack\",value:68,color:V.amber},\n  {name:\"Stripe\",  value:24,color:V.v400},\n  {name:\"Other\",   value:8, color:V.cyan},\n];\n\nexport default function AdminDashboard() {\n  const { data: stats, isLoading } = useQuery({\n    queryKey: [\"admin-overview\"],\n    queryFn: () => adminAPI.getStats().then(r => r.data.data),\n    refetchInterval: 60000,\n    retry: 2,\n  });\n\n  const { data: usersData } = useQuery({\n    queryKey: [\"admin-recent-users\"],\n    queryFn: () => adminAPI.getUsers({ limit:5, sort:\"newest\" }).then(r => r.data),\n    retry: 2,\n  });\n\n  const statCards = [\n    { label:\"Total Users\",       value: num(stats?.users?.total||0),       sub:stats?.users?.growth,       color:V.v400,  icon:Users         },\n    { label:\"Platform Revenue\",  value: fmt(stats?.revenue?.total||0),     sub:stats?.revenue?.growth,     color:V.green, icon:DollarSign    },\n    { label:\"Active Stores\",     value: num(stats?.stores?.active||0),     sub:stats?.stores?.growth,      color:V.cyan,  icon:Store         },\n    { label:\"Total Orders\",      value: num(stats?.orders?.total||0),      sub:stats?.orders?.growth,      color:V.amber, icon:ShoppingCart  },\n    { label:\"DropOS Fees\",       value: fmt(stats?.fees?.total||0),        sub:undefined,                  color:V.v300,  icon:TrendingUp    },\n    { label:\"Avg MRR per Store\", value: fmt(stats?.avgMRR||0),             sub:undefined,                  color:V.green, icon:Activity      },\n  ];\n\n  const recentUsers = usersData?.data || [];\n  const gwData = stats?.gatewayStats?.length ? stats.gatewayStats.map((g:any)=>({name:g.gateway,value:g._count?.id||0,color:g.gateway===\"PAYSTACK\"?V.amber:V.v400})) : DEMO_GW;\n  const revenueData = stats?.monthlyRevenue?.length ? stats.monthlyRevenue : DEMO_REVENUE;\n\n  return (\n    <div>\n      {/* Header */}\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{ marginBottom:24 }}>\n        <h1 style={{ fontSize:\"clamp(20px,4vw,26px)\", fontWeight:900, letterSpacing:\"-0.04em\", color:\"#fff\", margin:\"0 0 4px\" }}>Platform Overview</h1>\n        <p style={{ fontSize:13, color:\"rgba(255,255,255,0.35)\", margin:0 }}>\n          All merchants · {new Date().toLocaleDateString(\"en-NG\",{month:\"long\",year:\"numeric\"})}\n        </p>\n      </motion.div>\n\n      {/* Stat grid */}\n      <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(auto-fill,minmax(160px,1fr))\", gap:12, marginBottom:24 }}>\n        {statCards.map((s,i) => <StatCard key={s.label} {...s} delay={i*0.06}/>)}\n      </div>\n\n      {/* Charts row */}\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 280px\", gap:16, marginBottom:20 }} className=\"admin-charts\">\n        {/* Revenue chart */}\n        <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.4}}\n          style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:20, flexWrap:\"wrap\", gap:8 }}>\n            <p style={{ fontSize:14, fontWeight:700, color:\"#fff\", margin:0 }}>Platform Revenue</p>\n            <Link href=\"/admin/analytics\" style={{ display:\"flex\", alignItems:\"center\", gap:4, fontSize:12, color:V.v300, textDecoration:\"none\", fontWeight:600 }}>\n              Full report <ArrowUpRight size={12}/>\n            </Link>\n          </div>\n          <ResponsiveContainer width=\"100%\" height={200}>\n            <AreaChart data={revenueData} margin={{top:0,right:0,bottom:0,left:0}}>\n              <defs>\n                <linearGradient id=\"gr\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"5%\" stopColor={V.v400} stopOpacity={0.2}/>\n                  <stop offset=\"95%\" stopColor={V.v400} stopOpacity={0}/>\n                </linearGradient>\n              </defs>\n              <XAxis dataKey=\"month\" tick={{fill:\"rgba(255,255,255,0.3)\",fontSize:10}} axisLine={false} tickLine={false}/>\n              <YAxis tick={{fill:\"rgba(255,255,255,0.3)\",fontSize:10}} axisLine={false} tickLine={false} tickFormatter={v=>`₦${(v/1000000).toFixed(1)}M`}/>\n              <Tooltip contentStyle={{background:\"#181230\",border:\"1px solid rgba(107,53,232,0.3)\",borderRadius:10,fontSize:12}} formatter={(v:any)=>[fmt(v),\"Revenue\"]}/>\n              <Area type=\"monotone\" dataKey=\"revenue\" stroke={V.v400} strokeWidth={2} fill=\"url(#gr)\"/>\n            </AreaChart>\n          </ResponsiveContainer>\n        </motion.div>\n\n        {/* Gateway pie */}\n        <motion.div initial={{opacity:0,x:16}} animate={{opacity:1,x:0}} transition={{delay:0.45}}\n          style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n          <p style={{ fontSize:14, fontWeight:700, color:\"#fff\", margin:\"0 0 16px\" }}>Payment Gateways</p>\n          <div style={{ display:\"flex\", justifyContent:\"center\" }}>\n            <PieChart width={140} height={140}>\n              <Pie data={gwData} cx={65} cy={65} innerRadius={38} outerRadius={60} dataKey=\"value\" strokeWidth={0}>\n                {gwData.map((g:any,i:number) => <Cell key={i} fill={g.color}/>)}\n              </Pie>\n            </PieChart>\n          </div>\n          <div style={{ display:\"flex\", flexDirection:\"column\", gap:8, marginTop:8 }}>\n            {gwData.map((g:any) => (\n              <div key={g.name} style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n                <div style={{ width:8, height:8, borderRadius:\"50%\", background:g.color, flexShrink:0 }}/>\n                <span style={{ fontSize:12, color:\"rgba(255,255,255,0.6)\", flex:1 }}>{g.name}</span>\n                <span style={{ fontSize:12, fontWeight:700, color:\"#fff\" }}>{g.value}{typeof g.value===\"number\"&&g.value<100?\"%\":\"\"}</span>\n              </div>\n            ))}\n          </div>\n        </motion.div>\n      </div>\n\n      {/* Recent users */}\n      <motion.div initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} transition={{delay:0.5}}\n        style={{ padding:20, borderRadius:16, background:\"rgba(255,255,255,0.03)\", border:\"1px solid rgba(255,255,255,0.06)\" }}>\n        <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:16 }}>\n          <p style={{ fontSize:14, fontWeight:700, color:\"#fff\", margin:0 }}>Recent Signups</p>\n          <Link href=\"/admin/users\" style={{ display:\"flex\", alignItems:\"center\", gap:4, fontSize:12, color:V.v300, textDecoration:\"none\", fontWeight:600 }}>\n            All users <ChevronRight size={12}/>\n          </Link>\n        </div>\n        {recentUsers.length === 0 ? (\n          <p style={{ fontSize:13, color:\"rgba(255,255,255,0.3)\", textAlign:\"center\", padding:\"24px 0\", margin:0 }}>No users yet</p>\n        ) : (\n          <div style={{ display:\"flex\", flexDirection:\"column\", gap:6 }}>\n            {recentUsers.slice(0,5).map((u:any,i:number) => (\n              <motion.div key={u.id} initial={{opacity:0,x:-8}} animate={{opacity:1,x:0}} transition={{delay:0.52+i*0.04}}\n                style={{ display:\"flex\", alignItems:\"center\", gap:12, padding:\"10px 12px\", borderRadius:12, background:\"rgba(255,255,255,0.02)\" }}>\n                <div style={{ width:32, height:32, borderRadius:10, background:`linear-gradient(135deg,${V.v500},${V.v700})`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:12, fontWeight:800, color:\"#fff\", flexShrink:0 }}>\n                  {u.name?.charAt(0)||\"U\"}\n                </div>\n                <div style={{ flex:1, minWidth:0 }}>\n                  <p style={{ fontSize:13, fontWeight:600, color:\"rgba(255,255,255,0.8)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{u.name}</p>\n                  <p style={{ fontSize:11, color:\"rgba(255,255,255,0.3)\", margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{u.email}</p>\n                </div>\n                <div style={{ textAlign:\"right\", flexShrink:0 }}>\n                  <span style={{ fontSize:10, fontWeight:700, color:u.status===\"ACTIVE\"?V.green:V.amber, background:u.status===\"ACTIVE\"?\"rgba(16,185,129,0.1)\":\"rgba(245,158,11,0.1)\", padding:\"2px 8px\", borderRadius:99 }}>{u.status}</span>\n                  <p style={{ fontSize:10, color:\"rgba(255,255,255,0.25)\", margin:\"3px 0 0\" }}>{new Date(u.createdAt).toLocaleDateString()}</p>\n                </div>\n                <Link href={`/admin/users/${u.id}`} style={{ textDecoration:\"none\" }}>\n                  <ChevronRight size={14} color=\"rgba(255,255,255,0.2)\"/>\n                </Link>\n              </motion.div>\n            ))}\n          </div>\n        )}\n      </motion.div>\n\n      <style>{`\n        @media(max-width:700px){\n          .admin-charts{grid-template-columns:1fr!important}\n        }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/users/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { Search, Trash2, ChevronLeft, ChevronRight, Users, UserCheck, Ban, Crown, Filter } from \"lucide-react\";\nimport Link from \"next/link\";\nimport { motion } from \"framer-motion\";\nimport toast from \"react-hot-toast\";\n\nconst V = { v500:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\", faint:\"rgba(255,255,255,0.02)\" };\n\nconst STATUS_COLOR: Record<string,string> = { ACTIVE:V.green, PENDING_VERIFICATION:V.amber, SUSPENDED:V.red, BANNED:V.red };\nconst PLAN_COLOR:   Record<string,string> = { FREE:\"rgba(255,255,255,0.3)\", GROWTH:V.v400, PRO:\"#F59E0B\", ENTERPRISE:\"#10B981\" };\n\nexport default function AdminUsersPage() {\n  const qc = useQueryClient();\n  const [page, setPage]     = useState(1);\n  const [search, setSearch] = useState(\"\");\n  const [status, setStatus] = useState(\"\");\n  const [plan, setPlan]     = useState(\"\");\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-users\", page, search, status, plan],\n    queryFn:  () => adminAPI.getUsers({ page, limit:20, search, status, plan }).then((r: any) => r.data),\n    placeholderData: (prev: any) => prev,\n  });\n\n  const deleteMut = useMutation({\n    mutationFn: (id:string) => adminAPI.deleteUser(id),\n    onSuccess: () => { toast.success(\"User deleted\"); qc.invalidateQueries({queryKey:[\"admin-users\"]}); },\n    onError: () => toast.error(\"Delete failed\"),\n  });\n\n  const suspendMut = useMutation({\n    mutationFn: ({id,status}:{id:string;status:string}) => status === \"BANNED\" ? adminAPI.banUser(id) : adminAPI.unbanUser(id),\n    onSuccess: () => { toast.success(\"User updated\"); qc.invalidateQueries({queryKey:[\"admin-users\"]}); },\n  });\n\n  const users = (data as any)?.data || [];\n  const meta  = (data as any)?.meta || { total:0, page:1, pages:1 };\n\n  return (\n    <div>\n      <motion.div initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}} style={{ marginBottom:20 }}>\n        <h1 style={{ fontSize:22, fontWeight:900, letterSpacing:\"-0.04em\", color:t.text, margin:\"0 0 4px\" }}>Users</h1>\n        <p style={{ fontSize:13, color:t.muted, margin:0 }}>{meta.total?.toLocaleString()||0} total users</p>\n      </motion.div>\n\n      {/* Filters */}\n      <div style={{ display:\"flex\", gap:10, marginBottom:16, flexWrap:\"wrap\" }}>\n        <div style={{ flex:1, minWidth:200, display:\"flex\", alignItems:\"center\", gap:8, padding:\"9px 14px\", borderRadius:12, background:t.card, border:`1px solid ${t.border}` }}>\n          <Search size={14} style={{ color:t.muted, flexShrink:0 }}/>\n          <input value={search} onChange={e=>{setSearch(e.target.value);setPage(1);}} placeholder=\"Search by name or email...\"\n            style={{ flex:1, background:\"transparent\", border:\"none\", outline:\"none\", color:t.text, fontSize:13, fontFamily:\"inherit\" }}/>\n        </div>\n        <select value={status} onChange={e=>{setStatus(e.target.value);setPage(1);}}\n          style={{ padding:\"9px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:t.card, color:t.muted, fontSize:13, outline:\"none\", cursor:\"pointer\", fontFamily:\"inherit\" }}>\n          <option value=\"\">All Status</option>\n          <option value=\"ACTIVE\">Active</option>\n          <option value=\"PENDING_VERIFICATION\">Pending</option>\n          <option value=\"SUSPENDED\">Suspended</option>\n          <option value=\"BANNED\">Banned</option>\n        </select>\n        <select value={plan} onChange={e=>{setPlan(e.target.value);setPage(1);}}\n          style={{ padding:\"9px 14px\", borderRadius:12, border:`1px solid ${t.border}`, background:t.card, color:t.muted, fontSize:13, outline:\"none\", cursor:\"pointer\", fontFamily:\"inherit\" }}>\n          <option value=\"\">All Plans</option>\n          <option value=\"FREE\">Free</option>\n          <option value=\"GROWTH\">Growth</option>\n          <option value=\"PRO\">Pro</option>\n        </select>\n      </div>\n\n      {/* Table */}\n      <div style={{ borderRadius:16, overflow:\"hidden\", background:t.card, border:`1px solid ${t.border}` }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:\"2fr 1.5fr 1fr 1fr 100px\", gap:12, padding:\"10px 16px\", borderBottom:`1px solid ${t.border}` }}>\n          {[\"User\",\"Email\",\"Plan\",\"Status\",\"Actions\"].map(h => (\n            <p key={h} style={{ fontSize:10, fontWeight:700, textTransform:\"uppercase\", letterSpacing:\"0.1em\", color:t.muted, margin:0 }}>{h}</p>\n          ))}\n        </div>\n        {isLoading ? (\n          <div style={{ textAlign:\"center\", padding:\"40px\", color:t.muted }}>Loading users...</div>\n        ) : users.length === 0 ? (\n          <div style={{ textAlign:\"center\", padding:\"40px\" }}>\n            <Users size={28} style={{ color:t.muted, margin:\"0 auto 10px\" }}/>\n            <p style={{ color:t.muted, fontSize:13, margin:0 }}>No users found</p>\n          </div>\n        ) : users.map((u:any, i:number) => {\n          const statusColor = STATUS_COLOR[u.status] || V.amber;\n          const planColor   = PLAN_COLOR[u.subscription?.plan || \"FREE\"];\n          return (\n            <motion.div key={u.id} initial={{opacity:0}} animate={{opacity:1}} transition={{delay:i*0.02}}\n              style={{ display:\"grid\", gridTemplateColumns:\"2fr 1.5fr 1fr 1fr 100px\", gap:12, alignItems:\"center\", padding:\"12px 16px\", borderBottom:`1px solid ${t.border}`, background:i%2===0?\"transparent\":t.faint }}>\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:10, minWidth:0 }}>\n                <div style={{ width:32, height:32, borderRadius:10, background:`linear-gradient(135deg,${V.v500},#3D1C8A)`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontSize:12, fontWeight:800, color:\"#fff\", flexShrink:0 }}>\n                  {u.name?.charAt(0)||\"U\"}\n                </div>\n                <div style={{ minWidth:0 }}>\n                  <Link href={`/admin/users/${u.id}`} style={{ fontSize:13, fontWeight:700, color:t.text, textDecoration:\"none\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\", display:\"block\" }}>{u.name}</Link>\n                  <p style={{ fontSize:11, color:t.muted, margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{new Date(u.createdAt).toLocaleDateString()}</p>\n                </div>\n              </div>\n              <p style={{ fontSize:12, color:t.muted, margin:0, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{u.email}</p>\n              <span style={{ fontSize:11, fontWeight:700, color:planColor, background:`${planColor}18`, padding:\"3px 10px\", borderRadius:99, width:\"fit-content\" }}>\n                {u.subscription?.plan || \"FREE\"}\n              </span>\n              <span style={{ fontSize:11, fontWeight:700, color:statusColor, background:`${statusColor}15`, padding:\"3px 10px\", borderRadius:99, width:\"fit-content\" }}>\n                {u.status?.replace(\"_\",\" \")||\"ACTIVE\"}\n              </span>\n              <div style={{ display:\"flex\", gap:4 }}>\n                <button onClick={()=>suspendMut.mutate({id:u.id,status:u.status===\"ACTIVE\"?\"SUSPENDED\":\"ACTIVE\"})}\n                  style={{ width:28, height:28, borderRadius:8, border:\"none\", background:u.status===\"ACTIVE\"?\"rgba(239,68,68,0.1)\":\"rgba(16,185,129,0.1)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}\n                  title={u.status===\"ACTIVE\"?\"Suspend\":\"Activate\"}>\n                  {u.status===\"ACTIVE\"?<Ban size={12} color={V.red}/>:<UserCheck size={12} color={V.green}/>}\n                </button>\n                <button onClick={()=>{if(confirm(\"Delete user?\")){deleteMut.mutate(u.id);}}}\n                  style={{ width:28, height:28, borderRadius:8, border:\"none\", background:\"rgba(239,68,68,0.08)\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  <Trash2 size={12} color={V.red}/>\n                </button>\n              </div>\n            </motion.div>\n          );\n        })}\n      </div>\n\n      {/* Pagination */}\n      {meta.pages > 1 && (\n        <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:10, marginTop:16 }}>\n          <button onClick={()=>setPage(p=>Math.max(1,p-1))} disabled={page===1}\n            style={{ width:32, height:32, borderRadius:10, border:`1px solid ${t.border}`, background:t.faint, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", opacity:page===1?0.3:1 }}>\n            <ChevronLeft size={14} color={t.muted}/>\n          </button>\n          <span style={{ fontSize:13, color:t.muted }}>Page {page} of {meta.pages}</span>\n          <button onClick={()=>setPage(p=>Math.min(meta.pages,p+1))} disabled={page===meta.pages}\n            style={{ width:32, height:32, borderRadius:10, border:`1px solid ${t.border}`, background:t.faint, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", opacity:page===meta.pages?0.3:1 }}>\n            <ChevronRight size={14} color={t.muted}/>\n          </button>\n        </div>\n      )}\n    </div>\n  );\n}\n","frontend/src/app/admin/users/[userId]/page.tsx":"\"use client\";\n\nimport { useTheme } from \"next-themes\";\nimport { useState } from \"react\";\nimport { useParams, useRouter } from \"next/navigation\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../../lib/api\";\n\nimport { useForm } from \"react-hook-form\";\nimport { zodResolver } from \"@hookform/resolvers/zod\";\nimport { z } from \"zod\";\nimport toast from \"react-hot-toast\";\nimport {\n  ArrowLeft, Edit2, Save, X, Trash2, Flag, Globe, Phone,\n  MapPin, Mail, Shield, Key, Ban, UserCheck, Copy, CheckCircle\n} from \"lucide-react\";\nimport Link from \"next/link\";\nimport { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from \"recharts\";\n\nconst MONTHS = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\", \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"];\n\nexport default function UserDetailPage() {\n  const { userId }  = useParams<{ userId: string }>();\n  const { theme }   = useTheme();\n  const dark        = theme === \"dark\";\n  const router      = useRouter();\n  const qc          = useQueryClient();\n  const [tab, setTab]         = useState<\"overview\" | \"stores\" | \"payments\" | \"account\">(\"overview\");\n  const [editing, setEditing] = useState(false);\n  const [confirmDel, setConfirmDel] = useState(false);\n\n  const card = \"bg-[var(--bg-card)] border-[var(--border)]\";\n  const inp  = \"bg-[var(--bg-card)] border-[var(--border)] text-[var(--text-primary)]\";\n  const tx   = \"text-[var(--text-primary)]\";\n  const sub  = \"text-[var(--text-tertiary)]\";\n  const GRAD = \"linear-gradient(135deg,#7c3aed,#a855f7)\";\n\n  const { data: res, isLoading } = useQuery({\n    queryKey: [\"admin-user\", userId],\n    queryFn:  () => adminAPI.getUser(userId).then((r) => r.data.data),\n  });\n  const user = res;\n\n  const schema = z.object({\n    name:          z.string().min(2).optional(),\n    email:         z.string().email().optional(),\n    phone:         z.string().optional(),\n    status:        z.enum([\"ACTIVE\", \"SUSPENDED\", \"BANNED\"]).optional(),\n    emailVerified: z.boolean().optional(),\n    twoFAEnabled:  z.boolean().optional(),\n    adminNotes:    z.string().optional(),\n    flags:         z.array(z.string()).optional(),\n    country:       z.string().optional(),\n    city:          z.string().optional(),\n  });\n\n  const { register, handleSubmit, watch, setValue, reset, formState: { isDirty } } = useForm({\n    resolver: zodResolver(schema),\n    values:   user ? {\n      name:          user.name,\n      email:         user.email,\n      phone:         user.phone || \"\",\n      status:        user.status,\n      emailVerified: user.emailVerified,\n      twoFAEnabled:  user.twoFAEnabled,\n      adminNotes:    user.adminNotes || \"\",\n      flags:         user.flags || [],\n      country:       user.country || \"\",\n      city:          user.city || \"\",\n    } : undefined,\n  });\n\n  const currentFlags = watch(\"flags\") || [];\n  const currentStatus = watch(\"status\");\n\n  const updateUser = useMutation({\n    mutationFn: (data: any) => adminAPI.updateSubscription(userId, data),\n    onSuccess: () => {\n      toast.success(\"User saved\");\n      qc.invalidateQueries({ queryKey: [\"admin-user\", userId] });\n      setEditing(false);\n    },\n    onError: () => toast.error(\"Save failed\"),\n  });\n\n  const updateSub = useMutation({\n    mutationFn: (data: any) => adminAPI.updateSubscription(userId, data),\n    onSuccess: () => { toast.success(\"Subscription updated\"); qc.invalidateQueries({ queryKey: [\"admin-user\", userId] }); },\n    onError:   () => toast.error(\"Update failed\"),\n  });\n\n  const deleteUser = useMutation({\n    mutationFn: () => adminAPI.deleteUser(userId),\n    onSuccess: () => { toast.success(\"User deleted\"); router.push(\"/admin/users\"); },\n    onError:   () => toast.error(\"Delete failed\"),\n  });\n\n  const impersonateMut = useMutation({\n    mutationFn: () => adminAPI.post(`/admin/users/${userId}/impersonate`, {}),\n    onSuccess: (res: any) => {\n      const { accessToken, user: u } = res.data.data;\n      // Store token and redirect to dashboard\n      localStorage.setItem(\"dropos_access_token\", accessToken);\n      toast.success(`Now viewing as ${u.email}`);\n      setTimeout(() => { window.location.href = \"/dashboard\"; }, 800);\n    },\n    onError: () => toast.error(\"Impersonation failed\"),\n  });\n\n  const toggleFlag = (flag: string) => {\n    const flags = currentFlags.includes(flag)\n      ? currentFlags.filter((f: string) => f !== flag)\n      : [...currentFlags, flag];\n    setValue(\"flags\", flags, { shouldDirty: true });\n  };\n\n  if (isLoading) return (\n      <div className=\"flex items-center justify-center h-64\">\n        <div className=\"w-8 h-8 rounded-full border-2 border-violet-500 border-t-transparent animate-spin\" />\n      </div>\n  );\n\n  if (!user) return (\n      <div className={`text-center py-20 ${sub}`}>User not found</div>\n  );\n\n  const TABS = [\n    { id: \"overview\",  label: \"Overview\" },\n    { id: \"stores\",    label: `Stores (${user.stores?.length || 0})` },\n    { id: \"payments\",  label: \"Payments\" },\n    { id: \"account\",   label: \"Account\" },\n  ] as const;\n\n  return (\n      <div className=\"max-w-4xl space-y-6\">\n        {/* Back */}\n        <Link href=\"/admin/users\" className={`inline-flex items-center gap-2 text-sm font-semibold ${sub} hover:text-violet-500 transition-all`}>\n          <ArrowLeft size={16} /> Back to Users\n        </Link>\n\n        {/* Header card */}\n        <div className={`rounded-2xl border p-6 bg-[var(--bg-card)]/60 border-[var(--border)]/50`}>\n          <div className=\"flex items-start justify-between\">\n            <div className=\"flex items-center gap-4\">\n              <div className=\"w-14 h-14 rounded-2xl flex items-center justify-center text-[var(--text-primary)] text-xl font-black shadow-lg shadow-violet-500/30\"\n                style={{ background: GRAD }}>\n                {user.name?.charAt(0)}\n              </div>\n              <div>\n                <h1 className={`text-xl font-black ${tx}`}>{user.name}</h1>\n                <p className={`text-sm ${sub}`}>{user.id} · Joined {new Date(user.createdAt).toLocaleDateString()}</p>\n              </div>\n            </div>\n\n            <div className=\"flex items-center gap-2\">\n              <span className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-semibold\n                ${user.status === \"ACTIVE\" ? \"bg-emerald-400/10 text-emerald-700 dark:text-emerald-400\"\n                  : \"bg-red-400/10 text-red-600 dark:text-red-400\"}`}>\n                <span className={`w-1.5 h-1.5 rounded-full ${user.status === \"ACTIVE\" ? \"bg-emerald-500\" : \"bg-red-500\"}`} />\n                {user.status}\n              </span>\n\n              {!editing ? (\n                <button onClick={() => setEditing(true)}\n                  className=\"flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-bold text-[var(--text-primary)] shadow-lg shadow-violet-500/20\"\n                  style={{ background: GRAD }}>\n                  <Edit2 size={12} /> Edit User\n                </button>\n              ) : (\n                <div className=\"flex gap-2\">\n                  <button onClick={handleSubmit((d) => updateUser.mutate(d))} disabled={updateUser.isPending}\n                    className=\"flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-bold text-[var(--text-primary)] bg-emerald-600 hover:bg-emerald-500 disabled:opacity-60\">\n                    <Save size={12} /> {updateUser.isPending ? \"Saving…\" : \"Save\"}\n                  </button>\n                  <button onClick={() => { setEditing(false); reset(); }}\n                    className={`px-4 py-2 rounded-xl text-xs font-bold border ${\"border-[var(--border-strong)] text-[var(--text-tertiary)]\"}`}>\n                    Cancel\n                  </button>\n                </div>\n              )}\n            </div>\n          </div>\n\n          {/* Flags */}\n          {user.flags?.length > 0 && (\n            <div className={`mt-4 flex flex-wrap gap-2 p-3 rounded-xl border border-red-500/20 bg-red-100 dark:bg-red-900/10`}>\n              <Flag size={13} className=\"text-red-500 mt-0.5\" />\n              {user.flags.map((f: string) => (\n                <span key={f} className=\"text-xs font-bold px-2.5 py-1 rounded-full bg-red-500/20 text-red-600 dark:text-red-400\">\n                  {f.replace(/_/g, \" \")}\n                </span>\n              ))}\n            </div>\n          )}\n        </div>\n\n        {/* Revenue summary */}\n        <div className=\"grid grid-cols-3 gap-4\">\n          {[\n            { l: \"Total Revenue\", v: `$${(user.totalRevenue || 0).toLocaleString()}`,  c: \"text-emerald-700 dark:text-emerald-400\" },\n            { l: \"Platform Fees\", v: `$${(user.platformFees || 0).toLocaleString()}`,  c: \"text-red-600 dark:text-red-400\" },\n            { l: \"Net Payouts\",   v: `$${(user.payouts || 0).toLocaleString()}`,       c: \"text-amber-700 dark:text-amber-400\" },\n          ].map((s) => (\n            <div key={s.l} className={`rounded-2xl border p-5 text-center bg-[var(--bg-card)]/60 border-[var(--border)]/50`}>\n              <div className={`text-2xl font-black ${s.c}`}>{s.v}</div>\n              <div className={`text-xs mt-1 ${sub}`}>{s.l}</div>\n            </div>\n          ))}\n        </div>\n\n        {/* Tabs */}\n        <div className={`flex gap-1 border-b border-[var(--border)]`}>\n          {TABS.map((t) => (\n            <button key={t.id} onClick={() => setTab(t.id as any)}\n              className={`pb-3 px-4 text-xs font-bold border-b-2 transition-all\n                ${tab === t.id ? \"border-violet-500 text-violet-500\" : `border-transparent ${sub}`}`}>\n              {t.label}\n            </button>\n          ))}\n        </div>\n\n        {/* ── OVERVIEW TAB ─────────────────────────────────────── */}\n        {tab === \"overview\" && (\n          <div className=\"space-y-4\">\n            <div className=\"grid grid-cols-2 gap-4\">\n              {[\n                { label: \"Full Name\", field: \"name\",    Icon: Mail },\n                { label: \"Email\",     field: \"email\",   Icon: Mail },\n                { label: \"Phone\",     field: \"phone\",   Icon: Phone },\n                { label: \"Location\",  field: \"city\",    Icon: MapPin },\n              ].map(({ label, field, Icon }) => (\n                <div key={field} className={`rounded-xl border p-4 ${card}`}>\n                  <div className=\"flex items-center gap-2 mb-2\">\n                    <Icon size={12} className=\"text-amber-700 dark:text-amber-400\" />\n                    <span className={`text-xs font-semibold ${sub}`}>{label}</span>\n                  </div>\n                  {editing ? (\n                    <input {...register(field as any)}\n                      className={`w-full rounded-lg px-3 py-2 text-sm border outline-none focus:border-violet-500 transition-all ${inp}`} />\n                  ) : (\n                    <span className={`text-sm font-semibold ${tx}`}>{(user as any)[field] || \"-\"}</span>\n                  )}\n                </div>\n              ))}\n            </div>\n\n            {/* Plan */}\n            <div className={`rounded-xl border p-4 flex items-center justify-between ${card}`}>\n              <div>\n                <div className={`text-xs font-semibold ${sub} mb-2`}>Subscription Plan</div>\n                <span className={`text-sm font-bold px-3 py-1.5 rounded-full\n                  ${user.subscription?.plan === \"ADVANCED\" ? \"bg-violet-400/10 text-violet-700 dark:text-violet-400\"\n                    : user.subscription?.plan === \"PRO\" ? \"bg-amber-400/10 text-amber-700 dark:text-amber-400\"\n                    : \"bg-[var(--bg-secondary)] text-[var(--text-tertiary)]\"}`}>\n                  {user.subscription?.plan || \"STARTER\"}\n                </span>\n              </div>\n              <div className=\"flex flex-col gap-2 items-end\">\n                <span className={`text-xs ${sub}`}>Expires {user.subscription?.currentPeriodEnd ? new Date(user.subscription.currentPeriodEnd).toLocaleDateString() : \"-\"}</span>\n                {editing && (\n                  <select onChange={(e) => updateSub.mutate({ plan: e.target.value })}\n                    defaultValue={user.subscription?.plan}\n                    className={`rounded-lg px-3 py-1.5 text-xs border outline-none focus:border-violet-500 ${inp}`}>\n                    {[\"STARTER\", \"PRO\", \"ADVANCED\"].map((p) => <option key={p}>{p}</option>)}\n                  </select>\n                )}\n              </div>\n            </div>\n\n            {/* Admin notes */}\n            <div className={`rounded-xl border p-4 ${card}`}>\n              <div className={`text-xs font-semibold ${sub} mb-2`}>Admin Notes</div>\n              {editing ? (\n                <textarea {...register(\"adminNotes\")} rows={3}\n                  className={`w-full rounded-lg px-3 py-2 text-sm border outline-none focus:border-violet-500 resize-none ${inp}`} />\n              ) : (\n                <p className={`text-sm ${tx}`}>{user.adminNotes || \"No notes.\"}</p>\n              )}\n            </div>\n\n            {/* Status (editing only) */}\n            {editing && (\n              <div className={`rounded-xl border p-4 ${card}`}>\n                <div className={`text-xs font-semibold ${sub} mb-3`}>Account Status</div>\n                <div className=\"flex gap-2\">\n                  {[\"ACTIVE\", \"SUSPENDED\", \"BANNED\"].map((s) => (\n                    <button key={s} type=\"button\"\n                      onClick={() => setValue(\"status\", s as any, { shouldDirty: true })}\n                      className={`px-4 py-2 rounded-lg text-xs font-bold capitalize border transition-all\n                        ${currentStatus === s\n                          ? s === \"ACTIVE\" ? \"bg-emerald-600 border-emerald-600 text-[var(--text-primary)]\"\n                            : s === \"SUSPENDED\" ? \"bg-amber-600 border-amber-600 text-[var(--text-primary)]\"\n                            : \"bg-red-600 border-red-600 text-[var(--text-primary)]\"\n                          : \"border-[var(--border-strong)] text-[var(--text-tertiary)]\"}`}>\n                      {s.toLowerCase()}\n                    </button>\n                  ))}\n                </div>\n              </div>\n            )}\n\n            {/* Delete */}\n            <div className={`rounded-xl border border-red-500/20 p-4 bg-red-100 dark:bg-red-900/10`}>\n              <p className=\"text-xs font-bold text-red-500 mb-3\">Danger Zone</p>\n              {!confirmDel ? (\n                <button onClick={() => setConfirmDel(true)}\n                  className=\"flex items-center gap-2 px-3 py-2 rounded-lg bg-red-600 hover:bg-red-500 text-[var(--text-primary)] text-xs font-bold\">\n                  <Trash2 size={12} /> Delete Account\n                </button>\n              ) : (\n                <div className=\"space-y-2\">\n                  <p className=\"text-xs text-red-600 dark:text-red-400\">Permanently deletes this user and ALL their data. Cannot be undone.</p>\n                  <div className=\"flex gap-2\">\n                    <button onClick={() => deleteUser.mutate()}\n                      className=\"px-3 py-2 rounded-lg bg-red-600 hover:bg-red-500 text-[var(--text-primary)] text-xs font-bold\">\n                      Yes, Delete Permanently\n                    </button>\n                    <button onClick={() => setConfirmDel(false)}\n                      className={`px-3 py-2 rounded-lg text-xs font-bold border ${\"border-[var(--border-strong)] text-[var(--text-tertiary)]\"}`}>\n                      Cancel\n                    </button>\n                  </div>\n                </div>\n              )}\n            </div>\n          </div>\n        )}\n\n        {/* ── STORES TAB ───────────────────────────────────────── */}\n        {tab === \"stores\" && (\n          <div className=\"space-y-4\">\n            {user.stores?.map((store: any) => (\n              <div key={store.id} className={`rounded-2xl border p-5 bg-[var(--bg-card)]/60 border-[var(--border)]/50`}>\n                <div className=\"flex items-start justify-between mb-4\">\n                  <div>\n                    <div className={`font-bold ${tx}`}>{store.name}</div>\n                    <div className={`text-xs mt-1 ${sub} flex items-center gap-1`}>\n                      <Globe size={11} /> {store.domain || store.slug + \".dropos.io\"}\n                    </div>\n                  </div>\n                  <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-semibold\n                    ${store.status === \"ACTIVE\" ? \"bg-emerald-400/10 text-emerald-700 dark:text-emerald-400\"\n                      : \"bg-red-400/10 text-red-600 dark:text-red-400\"}`}>\n                    <span className={`w-1.5 h-1.5 rounded-full ${store.status === \"ACTIVE\" ? \"bg-emerald-500\" : \"bg-red-500\"}`} />\n                    {store.status}\n                  </span>\n                </div>\n                <div className=\"grid grid-cols-3 gap-3\">\n                  {[\n                    { l: \"Orders\",   v: store._count?.orders || 0 },\n                    { l: \"Products\", v: store._count?.products || 0 },\n                    { l: \"Customers\",v: store._count?.customers || 0 },\n                  ].map((m) => (\n                    <div key={m.l} className={`rounded-lg p-3 text-center border bg-[#08080f] border-[var(--border)]`}>\n                      <div className={`text-base font-black ${tx}`}>{m.v}</div>\n                      <div className={`text-xs ${sub}`}>{m.l}</div>\n                    </div>\n                  ))}\n                </div>\n                <div className={`mt-3 text-xs ${sub}`}>\n                  <span className=\"font-semibold\">ID:</span> {store.id} ·{\" \"}\n                  <span className=\"font-semibold\">Created:</span> {new Date(store.createdAt).toLocaleDateString()}\n                </div>\n              </div>\n            ))}\n            {!user.stores?.length && (\n              <div className={`text-center py-12 ${sub}`}>No stores yet</div>\n            )}\n          </div>\n        )}\n\n        {/* ── PAYMENTS TAB ─────────────────────────────────────── */}\n        {tab === \"payments\" && (\n          <div className=\"space-y-4\">\n            <div className=\"grid grid-cols-3 gap-4\">\n              {[\n                { l: \"Total Revenue\", v: `$${(user.totalRevenue || 0).toLocaleString()}`, c: \"text-emerald-700 dark:text-emerald-400\" },\n                { l: \"Platform Fees\", v: `$${(user.platformFees || 0).toLocaleString()}`, c: \"text-red-600 dark:text-red-400\" },\n                { l: \"Net Payouts\",   v: `$${(user.payouts || 0).toLocaleString()}`,      c: \"text-amber-700 dark:text-amber-400\" },\n              ].map((s) => (\n                <div key={s.l} className={`rounded-xl border p-4 text-center bg-[var(--bg-card)]/60 border-[var(--border)]/50`}>\n                  <div className={`text-xl font-black ${s.c}`}>{s.v}</div>\n                  <div className={`text-xs ${sub} mt-0.5`}>{s.l}</div>\n                </div>\n              ))}\n            </div>\n            {user.stores?.map((store: any) => (\n              <div key={store.id}>\n                {store.payments?.length > 0 && (\n                  <div className={`rounded-xl border p-4 bg-[var(--bg-card)]/60 border-[var(--border)]/50`}>\n                    <div className={`text-xs font-semibold ${sub} mb-3`}>{store.name} - Recent Payments</div>\n                    <div className=\"space-y-2\">\n                      {store.payments.slice(0, 5).map((p: any, i: number) => (\n                        <div key={i} className=\"flex items-center justify-between text-sm\">\n                          <span className={`font-semibold ${tx}`}>${(p.amount || 0).toFixed(2)}</span>\n                          <span className=\"text-red-600 dark:text-red-400 text-xs\">-${(p.platformFee || 0).toFixed(2)} fee</span>\n                          <span className=\"text-emerald-700 dark:text-emerald-400 text-xs font-bold\">${(p.storeEarnings || 0).toFixed(2)}</span>\n                        </div>\n                      ))}\n                    </div>\n                  </div>\n                )}\n              </div>\n            ))}\n          </div>\n        )}\n\n        {/* ── ACCOUNT TAB ──────────────────────────────────────── */}\n        {tab === \"account\" && (\n          <div className=\"space-y-4\">\n            {/* Verification toggles */}\n            <div className=\"grid grid-cols-2 gap-4\">\n              {[\n                { l: \"Email Verified\", f: \"emailVerified\" as const },\n                { l: \"2FA Enabled\",    f: \"twoFAEnabled\" as const },\n              ].map(({ l, f }) => {\n                const val = watch(f);\n                return (\n                  <div key={f} className={`rounded-xl border p-4 flex items-center justify-between ${card}`}>\n                    <span className={`text-sm font-semibold ${tx}`}>{l}</span>\n                    {editing ? (\n                      <button type=\"button\" onClick={() => setValue(f, !val, { shouldDirty: true })}\n                        className={`px-3 py-1 rounded-full text-xs font-bold transition-all ${val ? \"bg-emerald-600 text-[var(--text-primary)]\" : \"bg-slate-600 text-[var(--text-secondary)]\"}`}>\n                        {val ? \"ON\" : \"OFF\"}\n                      </button>\n                    ) : (\n                      <span className={`text-xs font-bold px-3 py-1 rounded-full ${(user as any)[f] ? \"bg-emerald-600/20 text-emerald-700 dark:text-emerald-400\" : \"bg-slate-700 text-[var(--text-tertiary)]\"}`}>\n                        {(user as any)[f] ? \"Yes\" : \"No\"}\n                      </span>\n                    )}\n                  </div>\n                );\n              })}\n            </div>\n\n            {/* Account ID */}\n            <div className={`rounded-xl border p-4 ${card}`}>\n              <div className={`text-xs font-semibold ${sub} mb-2`}>Account ID</div>\n              <div className=\"flex items-center gap-2\">\n                <span className={`font-mono text-sm font-bold ${tx}`}>{user.id}</span>\n                <button onClick={() => { navigator.clipboard.writeText(user.id); toast.success(\"Copied!\"); }}\n                  className={`p-1.5 rounded-lg hover:bg-slate-700`}>\n                  <Copy size={12} className={sub} />\n                </button>\n              </div>\n            </div>\n\n            {/* Flags (editing) */}\n            {editing && (\n              <div className={`rounded-xl border p-4 ${card}`}>\n                <div className={`text-xs font-semibold ${sub} mb-3`}>Account Flags</div>\n                {[\"payment_dispute\", \"chargeback\", \"suspicious_activity\", \"policy_violation\", \"high_risk\"].map((f) => (\n                  <label key={f} className=\"flex items-center gap-3 py-1.5 cursor-pointer\">\n                    <input type=\"checkbox\" checked={currentFlags.includes(f)} onChange={() => toggleFlag(f)}\n                      className=\"accent-violet-500 w-4 h-4\" />\n                    <span className={`text-sm capitalize ${tx}`}>{f.replace(/_/g, \" \")}</span>\n                  </label>\n                ))}\n              </div>\n            )}\n\n            {/* Admin actions */}\n            <div className={`rounded-xl border p-4 ${card}`}>\n              <div className={`text-xs font-semibold ${sub} mb-3`}>Admin Actions</div>\n              <div className=\"flex flex-wrap gap-2\">\n                {[\n                  { label: \"Send Email\",     Icon: Mail,      cls: \"text-amber-700 dark:text-amber-400  bg-amber-600/20  hover:bg-amber-600/30\" },\n                  { label: \"Force Suspend\",  Icon: Ban,       cls: \"text-red-600 dark:text-red-400    bg-red-600/20    hover:bg-red-600/30\" },\n                  { label: \"Reset Password\", Icon: Key,       cls: \"text-amber-700 dark:text-amber-400 bg-violet-600/20 hover:bg-violet-600/30\" },\n                  { label: \"Verify Email\",   Icon: UserCheck, cls: \"text-emerald-700 dark:text-emerald-400 bg-emerald-600/20 hover:bg-emerald-600/30\" },\n                ].map(({ label, Icon, cls }) => (\n                  <button key={label}\n                    onClick={() => toast(\"Feature not yet implemented\", { icon: \"🚧\" })}\n                    className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-bold transition-all ${cls}`}>\n                    <Icon size={12} /> {label}\n                  </button>\n                ))}\n                {/* Impersonate */}\n                <button\n                  onClick={() => { if(confirm(`Log in as ${user?.email}? You will be redirected to their dashboard.`)) impersonateMut.mutate(); }}\n                  disabled={impersonateMut.isPending}\n                  className=\"flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-bold transition-all text-purple-700 dark:text-purple-300 bg-purple-600/20 hover:bg-purple-600/30 border border-purple-500/30\">\n                  👤 {impersonateMut.isPending ? \"Logging in...\" : \"Login as this user\"}\n                </button>\n              </div>\n            </div>\n          </div>\n        )}\n      </div>\n  );\n}","frontend/src/app/admin/payments/page.tsx":"\"use client\";\n\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { api, adminAPI } from \"../../../lib/api\";\n\nimport { CreditCard, ChevronLeft, ChevronRight, Search, X } from \"lucide-react\";\n\nconst statusColor: Record<string, string> = {\n  SUCCESS:  \"bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-400\",\n  PENDING:  \"bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400\",\n  FAILED:   \"bg-red-100 dark:bg-red-900/40 text-red-600 dark:text-red-400\",\n  REFUNDED: \"bg-slate-700 text-[var(--text-tertiary)]\",\n  DISPUTED: \"bg-orange-100 dark:bg-orange-900/40 text-orange-700 dark:text-orange-400\",\n};\n\nexport default function AdminPaymentsPage() {\n  \n  \n  const card = \"bg-[var(--bg-card)] border-[var(--border)]\";\n  const tx   = \"text-[var(--text-primary)]\";\n  const sub  = \"text-[var(--text-tertiary)]\";\n  const tRow = \"border-[var(--border)] hover:bg-[var(--bg-card)]\";\n\n  const [page, setPage]     = useState(1);\n  const [status, setStatus] = useState(\"\");\n  const [gateway, setGateway] = useState(\"\");\n\n  const { data, isLoading } = useQuery({\n    queryKey: [\"admin-payments\", page, status, gateway],\n    queryFn:  () => adminAPI.getPayments({ page, limit: 15, status, gateway }).then((r) => r.data),\n  });\n\n  const payments   = data?.data || [];\n  const pagination = data?.pagination;\n  const totals     = data?.totals;\n\n  return (\n      <div className=\"space-y-6\">\n        <div>\n          <h1 className={`text-2xl font-black tracking-tight ${tx}`}>Payments & Payouts</h1>\n          <p className={`text-sm mt-0.5 ${sub}`}>{pagination?.total || 0} total transactions</p>\n        </div>\n\n        {/* Totals */}\n        <div className=\"grid grid-cols-3 gap-4\">\n          {[\n            { l: \"Total Processed\",  v: `$${(totals?.amount        || 284200).toLocaleString()}`, c: \"text-emerald-700 dark:text-emerald-400\" },\n            { l: \"Platform Fees\",    v: `$${(totals?.platformFee   || 28420 ).toLocaleString()}`, c: \"text-amber-700 dark:text-amber-400\" },\n            { l: \"Store Payouts\",    v: `$${(totals?.storeEarnings || 255780).toLocaleString()}`, c: tx },\n          ].map(({ l, v, c }) => (\n            <div key={l} className={`rounded-2xl border p-5 text-center ${card}`}>\n              <div className={`text-2xl font-black ${c}`}>{v}</div>\n              <div className={`text-xs mt-0.5 ${sub}`}>{l}</div>\n            </div>\n          ))}\n        </div>\n\n        {/* Filters */}\n        <div className=\"flex flex-wrap gap-2\">\n          {[[\"\", \"All Status\"], [\"SUCCESS\", \"Success\"], [\"PENDING\", \"Pending\"], [\"FAILED\", \"Failed\"], [\"REFUNDED\", \"Refunded\"]].map(([v, l]) => (\n            <button key={v} onClick={() => { setStatus(v); setPage(1); }}\n              className={`px-3 py-2 rounded-xl text-xs font-semibold transition-all\n                ${status === v ? \"text-[var(--text-primary)]\" : `${sub} ${\"hover:bg-[var(--bg-card)]\"}`}`}\n              style={status === v ? { background: \"linear-gradient(135deg,#7c3aed,#a855f7)\" } : {}}>\n              {l}\n            </button>\n          ))}\n          <div className={`h-6 w-px self-center bg-slate-700`} />\n          {[[\"\", \"All Gateways\"], [\"STRIPE\", \"Stripe\"], [\"PAYSTACK\", \"Paystack\"], [\"FLUTTERWAVE\", \"Flutterwave\"]].map(([v, l]) => (\n            <button key={v} onClick={() => { setGateway(v); setPage(1); }}\n              className={`px-3 py-2 rounded-xl text-xs font-semibold transition-all\n                ${gateway === v ? \"text-[var(--text-primary)]\" : `${sub} ${\"hover:bg-[var(--bg-card)]\"}`}`}\n              style={gateway === v ? { background: \"linear-gradient(135deg,#7c3aed,#a855f7)\" } : {}}>\n              {l}\n            </button>\n          ))}\n        </div>\n\n        {/* Table */}\n        <div className={`rounded-2xl border overflow-hidden ${card}`}>\n          <table className=\"w-full text-sm\">\n            <thead>\n              <tr className={`border-b border-inherit text-xs ${sub}`}>\n                {[\"Order\", \"Customer\", \"Store / Owner\", \"Amount\", \"Fee\", \"Payout\", \"Gateway\", \"Date\", \"Status\"].map((h) => (\n                  <th key={h} className=\"text-left font-semibold px-4 py-3.5\">{h}</th>\n                ))}\n              </tr>\n            </thead>\n            <tbody>\n              {isLoading\n                ? Array.from({ length: 5 }).map((_, i) => (\n                    <tr key={i} className={`border-b border-[var(--border)]/50`}>\n                      {Array.from({ length: 9 }).map((_, j) => (\n                        <td key={j} className=\"px-4 py-4\">\n                          <div className={`h-3 rounded animate-pulse ${\"bg-[var(--bg-card)]\"}`} style={{ width: `${40 + Math.random() * 40}%` }} />\n                        </td>\n                      ))}\n                    </tr>\n                  ))\n                : payments.map((p: any) => (\n                    <tr key={p.id} className={`border-b transition-colors ${tRow}`}>\n                      <td className=\"px-4 py-4 font-mono text-xs font-bold text-violet-500\">\n                        {p.order?.orderNumber || \"-\"}\n                      </td>\n                      <td className=\"px-4 py-4\">\n                        <div className={`font-semibold text-xs ${tx}`}>{p.order?.customerName}</div>\n                        <div className={`text-xs ${sub} truncate max-w-[140px]`}>{p.order?.customerEmail}</div>\n                      </td>\n                      <td className=\"px-4 py-4\">\n                        <div className={`font-semibold text-xs ${tx}`}>{p.store?.name}</div>\n                        <div className={`text-xs ${sub}`}>{p.store?.owner?.name}</div>\n                      </td>\n                      <td className={`px-4 py-4 font-bold text-[var(--text-primary)]`}>\n                        ${(p.amount || 0).toFixed(2)}\n                      </td>\n                      <td className=\"px-4 py-4 text-xs font-bold text-red-600 dark:text-red-400\">\n                        -${(p.platformFee || 0).toFixed(2)}\n                      </td>\n                      <td className=\"px-4 py-4 text-xs font-bold text-emerald-700 dark:text-emerald-400\">\n                        ${(p.storeEarnings || 0).toFixed(2)}\n                      </td>\n                      <td className={`px-4 py-4 text-xs font-semibold ${sub}`}>{p.gateway}</td>\n                      <td className={`px-4 py-4 text-xs ${sub}`}>\n                        {new Date(p.createdAt).toLocaleDateString()}\n                      </td>\n                      <td className=\"px-4 py-4\">\n                        <span className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-xs font-semibold ${statusColor[p.status] || \"\"}`}>\n                          <span className=\"w-1.5 h-1.5 rounded-full bg-current opacity-70\" />\n                          {p.status}\n                        </span>\n                      </td>\n                    </tr>\n                  ))}\n              {!isLoading && !payments.length && (\n                <tr>\n                  <td colSpan={9} className={`py-16 text-center ${sub}`}>\n                    <CreditCard size={40} className=\"mx-auto mb-3 opacity-20\" />\n                    <p className=\"text-sm\">No payments found</p>\n                  </td>\n                </tr>\n              )}\n            </tbody>\n          </table>\n        </div>\n\n        {/* Pagination */}\n        {pagination && pagination.pages > 1 && (\n          <div className=\"flex items-center justify-between\">\n            <p className={`text-sm ${sub}`}>\n              Page {page} of {pagination.pages} · {pagination.total} total\n            </p>\n            <div className=\"flex gap-2\">\n              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}\n                className={`p-2 rounded-xl border disabled:opacity-40 border-[var(--border)] hover:bg-[var(--bg-card)]`}>\n                <ChevronLeft size={16} className={sub} />\n              </button>\n              <button onClick={() => setPage(p => Math.min(pagination.pages, p + 1))} disabled={page === pagination.pages}\n                className={`p-2 rounded-xl border disabled:opacity-40 border-[var(--border)] hover:bg-[var(--bg-card)]`}>\n                <ChevronRight size={16} className={sub} />\n              </button>\n            </div>\n          </div>\n        )}\n      </div>\n  );\n}\n","frontend/src/app/admin/analytics/page.tsx":"\"use client\";\n\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\n\nimport { AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from \"recharts\";\n\nconst MOCK_MONTHLY = [\n  { month: \"Jan\", revenue: 18400, fees: 1840, users: 12, stores: 8 },\n  { month: \"Feb\", revenue: 23600, fees: 2360, users: 18, stores: 12 },\n  { month: \"Mar\", revenue: 28900, fees: 2890, users: 22, stores: 15 },\n  { month: \"Apr\", revenue: 35200, fees: 3520, users: 31, stores: 21 },\n  { month: \"May\", revenue: 43800, fees: 4380, users: 40, stores: 28 },\n  { month: \"Jun\", revenue: 52100, fees: 5210, users: 52, stores: 36 },\n  { month: \"Jul\", revenue: 61400, fees: 6140, users: 67, stores: 44 },\n];\n\nconst GW_COLORS = [\"#7c3aed\", \"#f59e0b\", \"#10b981\"];\nconst GW_DATA   = [{ name: \"Stripe\", value: 58 }, { name: \"Paystack\", value: 28 }, { name: \"Flutterwave\", value: 14 }];\n\nexport default function AdminAnalyticsPage() {\n  \n  \n  const [period, setPeriod] = useState(\"7d\");\n  const card = \"bg-[var(--bg-card)] border-[var(--border)]\";\n  const tx   = \"text-[var(--text-primary)]\";\n  const sub  = \"text-[var(--text-tertiary)]\";\n  const tip  = { background: \"var(--chart-tooltip-bg)\", border: \"1px solid var(--chart-tooltip-border)\", borderRadius: 12, fontSize: 12 };\n\n  const { data: stats , isLoading } = useQuery({\n    queryKey: [\"admin-dashboard\"],\n    queryFn:  () => adminAPI.getStats().then((r) => r.data.data),\n  });\n\n  const monthly = stats?.monthlyRevenue?.length ? stats.monthlyRevenue : MOCK_MONTHLY;\n\n  return (\n      <div className=\"space-y-6\">\n        <div className=\"flex items-center justify-between\">\n          <div>\n            <h1 className={`text-2xl font-black tracking-tight ${tx}`}>Platform Analytics</h1>\n            <p className={`text-sm mt-0.5 ${sub}`}>All-tenants overview</p>\n          </div>\n          <div className={`flex gap-1 rounded-xl p-1 border bg-[var(--bg-card)] border-[var(--border)]`}>\n            {[\"7d\", \"30d\", \"90d\"].map((p) => (\n              <button key={p} onClick={() => setPeriod(p)}\n                className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${period === p ? \"text-[var(--text-primary)]\" : sub}`}\n                style={period === p ? { background: \"linear-gradient(135deg,#7c3aed,#a855f7)\" } : {}}>\n                {p}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        {/* Summary KPIs */}\n        <div className=\"grid grid-cols-2 md:grid-cols-4 gap-4\">\n          {[\n            { l: \"Total Revenue\",     v: `$${(stats?.revenue?.total || 61400).toLocaleString()}`,           c: \"text-emerald-400\" },\n            { l: \"Platform Fees\",     v: `$${(stats?.platformFees?.total || 6140).toLocaleString()}`,        c: \"text-amber-400\" },\n            { l: \"Active Users\",      v: stats?.users?.active || 398,                                        c: tx },\n            { l: \"Total Stores\",      v: stats?.stores?.total || 44,                                         c: tx },\n          ].map(({ l, v, c }) => (\n            <div key={l} className={`rounded-2xl border p-5 ${card}`}>\n              <div className={`text-2xl font-black ${c}`}>{v}</div>\n              <div className={`text-xs mt-0.5 ${sub}`}>{l}</div>\n            </div>\n          ))}\n        </div>\n\n        {/* Revenue trend */}\n        <div className={`rounded-2xl border p-5 ${card}`}>\n          <h3 className={`font-bold mb-4 ${tx}`}>Revenue & Fees Trend</h3>\n          <ResponsiveContainer width=\"100%\" height={260}>\n            <AreaChart data={monthly}>\n              <defs>\n                <linearGradient id=\"revArea\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"5%\"  stopColor=\"#7c3aed\" stopOpacity={.25} />\n                  <stop offset=\"95%\" stopColor=\"#7c3aed\" stopOpacity={0} />\n                </linearGradient>\n                <linearGradient id=\"feeArea\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                  <stop offset=\"5%\"  stopColor=\"#f59e0b\" stopOpacity={.2} />\n                  <stop offset=\"95%\" stopColor=\"#f59e0b\" stopOpacity={0} />\n                </linearGradient>\n              </defs>\n              <XAxis dataKey=\"month\" tick={{ fill: \"var(--chart-axis)\", fontSize: 11 }} axisLine={false} tickLine={false} />\n              <YAxis tick={{ fill: \"var(--chart-axis)\", fontSize: 11 }} axisLine={false} tickLine={false}\n                tickFormatter={(v) => `$${(v / 1000).toFixed(0)}k`} />\n              <Tooltip contentStyle={tip}\n                formatter={(v: any, name: string) => [`$${Number(v).toLocaleString()}`, name === \"fees\" ? \"Platform Fees\" : \"Revenue\"]} />\n              <Area type=\"monotone\" dataKey=\"revenue\" stroke=\"#7c3aed\" strokeWidth={2.5} fill=\"url(#revArea)\" name=\"revenue\" />\n              <Area type=\"monotone\" dataKey=\"fees\"    stroke=\"#f59e0b\" strokeWidth={2}   fill=\"url(#feeArea)\" name=\"fees\" />\n            </AreaChart>\n          </ResponsiveContainer>\n        </div>\n\n        <div className=\"grid grid-cols-1 lg:grid-cols-2 gap-6\">\n          {/* New users bar chart */}\n          <div className={`rounded-2xl border p-5 ${card}`}>\n            <h3 className={`font-bold mb-4 ${tx}`}>New Users & Stores</h3>\n            <ResponsiveContainer width=\"100%\" height={200}>\n              <BarChart data={monthly}>\n                <XAxis dataKey=\"month\" tick={{ fill: \"var(--chart-axis)\", fontSize: 11 }} axisLine={false} tickLine={false} />\n                <YAxis tick={{ fill: \"var(--chart-axis)\", fontSize: 11 }} axisLine={false} tickLine={false} />\n                <Tooltip contentStyle={tip} />\n                <Bar dataKey=\"users\"  fill=\"#7c3aed\" radius={[4, 4, 0, 0]} name=\"Users\"  />\n                <Bar dataKey=\"stores\" fill=\"#a855f766\" radius={[4, 4, 0, 0]} name=\"Stores\" />\n              </BarChart>\n            </ResponsiveContainer>\n          </div>\n\n          {/* Gateway distribution */}\n          <div className={`rounded-2xl border p-5 ${card}`}>\n            <h3 className={`font-bold mb-4 ${tx}`}>Gateway Distribution</h3>\n            <div className=\"flex items-center gap-6\">\n              <ResponsiveContainer width=\"55%\" height={180}>\n                <PieChart>\n                  <Pie data={GW_DATA} cx=\"50%\" cy=\"50%\" innerRadius={48} outerRadius={72} dataKey=\"value\">\n                    {GW_DATA.map((_, i) => <Cell key={i} fill={GW_COLORS[i]} />)}\n                  </Pie>\n                  <Tooltip contentStyle={tip} formatter={(v: any) => [`${v}%`]} />\n                </PieChart>\n              </ResponsiveContainer>\n              <div className=\"flex-1 space-y-3\">\n                {GW_DATA.map((g, i) => (\n                  <div key={g.name}>\n                    <div className=\"flex items-center justify-between text-xs mb-1\">\n                      <div className=\"flex items-center gap-2\">\n                        <span className=\"w-2.5 h-2.5 rounded-full\" style={{ background: GW_COLORS[i] }} />\n                        <span className={sub}>{g.name}</span>\n                      </div>\n                      <span className={`font-black ${tx}`}>{g.value}%</span>\n                    </div>\n                    <div className={`h-1.5 rounded-full overflow-hidden ${\"bg-[var(--bg-card)]\"}`}>\n                      <div className=\"h-full rounded-full\" style={{ width: `${g.value}%`, background: GW_COLORS[i] }} />\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n  );\n}\n","frontend/src/app/admin/audit-logs/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { api } from \"../../../lib/api\";\nimport { Shield, Search, ChevronLeft, ChevronRight, User, Zap } from \"lucide-react\";\nimport { formatDistanceToNow } from \"date-fns\";\n\nconst ACTION_COLORS: Record<string, string> = {\n  CREATE: \"bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400\",\n  UPDATE: \"bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400\",\n  DELETE: \"bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400\",\n  LOGIN:  \"bg-violet-100 text-violet-700 dark:bg-violet-900/30 dark:text-violet-400\",\n};\n\nexport default function AuditLogsPage() {\n  const tx   = \"[color:var(--text-primary)]\";\n  const sub  = \"text-secondary\";\n  const card = \"[background:var(--bg-secondary)] [border-color:var(--border)]\";\n  const [page, setPage]     = useState(1);\n  const [search, setSearch] = useState(\"\");\n\n  const { data, isLoading } = useQuery({\n    queryKey: [\"audit-logs\", page, search],\n    queryFn:  () => api.get(\"/admin/audit-logs\", { params: { page, limit: 20, search } }).then(r => r.data),\n  });\n\n  const logs       = data?.data || [];\n  const pagination = data?.pagination;\n\n  return (\n      <div className=\"space-y-6\">\n        <div className=\"flex items-center justify-between\">\n          <div>\n            <h1 className={`text-2xl font-black tracking-tight ${tx}`}>Audit Logs</h1>\n            <p className={`text-sm mt-0.5 ${sub}`}>All admin and user actions across the platform</p>\n          </div>\n          <div className=\"w-10 h-10 rounded-2xl flex items-center justify-center\" style={{ background: \"var(--accent-dim)\" }}>\n            <Shield size={18} style={{ color: \"var(--accent)\" }} />\n          </div>\n        </div>\n\n        {/* Search */}\n        <div className={`flex items-center gap-2 rounded-xl px-3 py-2.5 border text-sm max-w-md [background:var(--bg-secondary)] [border-color:var(--border)]`}>\n          <Search size={14} className={sub} />\n          <input value={search} onChange={e => setSearch(e.target.value)} placeholder=\"Search action or user…\"\n            className=\"bg-transparent outline-none flex-1 [color:var(--text-primary)]\" />\n        </div>\n\n        {/* Table */}\n        <div className={`rounded-2xl border overflow-hidden ${card}`}>\n          <table className=\"w-full text-sm\">\n            <thead>\n              <tr className={`border-b border-inherit text-xs ${sub}`}>\n                {[\"Time\", \"User\", \"Action\", \"Entity\", \"Details\"].map(h => (\n                  <th key={h} className=\"text-left font-semibold px-5 py-3.5\">{h}</th>\n                ))}\n              </tr>\n            </thead>\n            <tbody>\n              {isLoading ? Array.from({ length: 8 }).map((_, i) => (\n                <tr key={i} className=\"border-b [border-color:var(--border)]/50\">\n                  {Array.from({ length: 5 }).map((_, j) => (\n                    <td key={j} className=\"px-5 py-4\">\n                      <div className=\"h-3 rounded animate-pulse [background:var(--bg-card)]\" style={{ width: `${40 + (j * 11) % 40}%` }} />\n                    </td>\n                  ))}\n                </tr>\n              )) : logs.map((log: any) => (\n                <tr key={log.id} className=\"border-b [border-color:var(--border)] hover:[background:var(--bg-card)] transition-colors\">\n                  <td className={`px-5 py-4 text-xs ${sub}`}>\n                    {formatDistanceToNow(new Date(log.createdAt), { addSuffix: true })}\n                  </td>\n                  <td className=\"px-5 py-4\">\n                    <div className=\"flex items-center gap-2\">\n                      <div className=\"w-6 h-6 rounded-full flex items-center justify-center text-white text-[10px] font-black flex-shrink-0\"\n                        style={{ background: \"linear-gradient(135deg,#7c3aed,#a855f7)\" }}>\n                        {log.userEmail?.charAt(0)?.toUpperCase() || \"?\"}\n                      </div>\n                      <span className={`text-xs ${tx}`}>{log.userEmail || \"System\"}</span>\n                    </div>\n                  </td>\n                  <td className=\"px-5 py-4\">\n                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-black ${ACTION_COLORS[log.action] || \"bg-[var(--bg-secondary)] [color:var(--text-secondary)]\"}`}>\n                      {log.action}\n                    </span>\n                  </td>\n                  <td className={`px-5 py-4 text-xs ${sub}`}>{log.entity}</td>\n                  <td className={`px-5 py-4 text-xs ${sub} max-w-xs truncate`}>\n                    {typeof log.details === \"string\" ? log.details : JSON.stringify(log.details)?.slice(0, 80)}\n                  </td>\n                </tr>\n              ))}\n              {!isLoading && !logs.length && (\n                <tr>\n                  <td colSpan={5} className={`py-16 text-center ${sub}`}>\n                    <Shield size={36} className=\"mx-auto mb-3 opacity-20\" />\n                    <p className=\"text-sm\">No audit logs found</p>\n                  </td>\n                </tr>\n              )}\n            </tbody>\n          </table>\n        </div>\n\n        {pagination && pagination.pages > 1 && (\n          <div className=\"flex items-center justify-between\">\n            <p className={`text-sm ${sub}`}>Page {page} of {pagination.pages}</p>\n            <div className=\"flex gap-2\">\n              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}\n                className=\"p-2 rounded-xl border disabled:opacity-40 [border-color:var(--border)] hover:[background:var(--bg-secondary)]\">\n                <ChevronLeft size={16} className={sub} />\n              </button>\n              <button onClick={() => setPage(p => Math.min(pagination.pages, p + 1))} disabled={page === pagination.pages}\n                className=\"p-2 rounded-xl border disabled:opacity-40 [border-color:var(--border)] hover:[background:var(--bg-secondary)]\">\n                <ChevronRight size={16} className={sub} />\n              </button>\n            </div>\n          </div>\n        )}\n      </div>\n  );\n}\n","frontend/src/app/admin/error-logs/page.tsx":"\"use client\";\n\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\n\nimport { CheckCircle, AlertCircle, ChevronDown, Shield, ChevronLeft, ChevronRight } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nexport default function ErrorLogsPage() {\n  \n  \n  const qc   = useQueryClient();\n  const card = \"bg-[var(--bg-card)] border-[var(--border)]\";\n  const tx   = \"text-[var(--text-primary)]\";\n  const sub  = \"text-[var(--text-tertiary)]\";\n  const [page, setPage]   = useState(1);\n  const [filter, setFilter] = useState(\"\");\n  const [expand, setExpand] = useState<string | null>(null);\n\n  const { data, isLoading } = useQuery({\n    queryKey: [\"error-logs\", page, filter],\n    queryFn:  () => adminAPI.getErrorLogs({ page, limit: 15, resolved: filter || undefined }).then((r) => r.data),\n  });\n\n  const resolveLog = useMutation({\n    mutationFn: (id: string) => adminAPI.resolveError(id),\n    onSuccess: () => { toast.success(\"Marked as resolved\"); qc.invalidateQueries({ queryKey: [\"error-logs\"] }); },\n    onError:   () => toast.error(\"Failed to resolve\"),\n  });\n\n  const logs       = data?.data || [];\n  const pagination = data?.pagination;\n\n  return (\n      <div className=\"space-y-6 max-w-4xl\">\n        <div>\n          <h1 className={`text-2xl font-black tracking-tight ${tx}`}>Error Logs</h1>\n          <p className={`text-sm mt-0.5 ${sub}`}>{pagination?.total || 0} total errors</p>\n        </div>\n\n        {/* Filters */}\n        <div className=\"flex gap-2\">\n          {[[\"\", \"All\"], [\"false\", \"Unresolved\"], [\"true\", \"Resolved\"]].map(([v, l]) => (\n            <button key={v} onClick={() => { setFilter(v); setPage(1); }}\n              className={`px-3 py-2 rounded-xl text-xs font-semibold transition-all\n                ${filter === v ? \"text-[var(--text-primary)]\" : `${sub} ${\"hover:bg-[var(--bg-card)]\"}`}`}\n              style={filter === v ? { background: \"linear-gradient(135deg,#7c3aed,#a855f7)\" } : {}}>\n              {l}\n            </button>\n          ))}\n        </div>\n\n        {/* Logs */}\n        {isLoading ? (\n          <div className=\"space-y-3\">\n            {[1, 2, 3].map((i) => (\n              <div key={i} className={`rounded-2xl border p-5 animate-pulse ${card}`}>\n                <div className={`h-4 w-64 rounded mb-2 ${\"bg-[var(--bg-card)]\"}`} />\n                <div className={`h-3 w-40 rounded ${\"bg-[var(--bg-card)]\"}`} />\n              </div>\n            ))}\n          </div>\n        ) : logs.length === 0 ? (\n          <div className={`text-center py-12 ${sub}`}>\n            <Shield size={40} className=\"mx-auto mb-3 opacity-20\" />\n            <p className=\"text-sm\">No error logs found</p>\n          </div>\n        ) : (\n          <div className=\"space-y-3\">\n            {logs.map((log: any) => (\n              <div key={log.id} className={`rounded-2xl border overflow-hidden ${card}`}>\n                <button className=\"w-full text-left p-5\" onClick={() => setExpand(expand === log.id ? null : log.id)}>\n                  <div className=\"flex items-start justify-between gap-3\">\n                    <div className=\"flex items-center gap-3 flex-1\">\n                      <div className={`p-2 rounded-lg flex-shrink-0 ${log.resolved ? \"bg-emerald-100 dark:bg-emerald-900/30\" : \"bg-red-100 dark:bg-red-900/30\"}`}>\n                        {log.resolved\n                          ? <CheckCircle size={14} className=\"text-emerald-500\" />\n                          : <AlertCircle size={14} className=\"text-red-500\" />}\n                      </div>\n                      <div className=\"flex-1 min-w-0\">\n                        <div className={`font-semibold text-sm truncate ${tx}`}>{log.message}</div>\n                        <div className={`text-xs mt-0.5 ${sub}`}>\n                          {log.method} {log.path} · Status {log.statusCode} ·{\" \"}\n                          {new Date(log.createdAt).toLocaleString()}\n                        </div>\n                      </div>\n                    </div>\n                    <div className=\"flex items-center gap-2 flex-shrink-0\">\n                      {!log.resolved && (\n                        <button onClick={(e) => { e.stopPropagation(); resolveLog.mutate(log.id); }}\n                          className=\"px-3 py-1.5 rounded-lg text-xs font-bold bg-emerald-600/20 text-emerald-700 dark:text-emerald-400 hover:bg-emerald-600/30 transition-all\">\n                          Resolve\n                        </button>\n                      )}\n                      <ChevronDown size={14} className={`${sub} transition-transform ${expand === log.id ? \"rotate-180\" : \"\"}`} />\n                    </div>\n                  </div>\n                </button>\n\n                {expand === log.id && log.stack && (\n                  <div className={`px-5 pb-5 border-t border-[var(--border)]/50`}>\n                    <div className={`mt-4 rounded-xl p-4 font-mono text-xs overflow-x-auto whitespace-pre-wrap bg-slate-950 text-[var(--text-secondary)]`}>\n                      {log.stack}\n                    </div>\n                    {log.userId && (\n                      <p className={`text-xs mt-2 ${sub}`}>User ID: {log.userId}</p>\n                    )}\n                  </div>\n                )}\n              </div>\n            ))}\n          </div>\n        )}\n\n        {/* Pagination */}\n        {pagination && pagination.pages > 1 && (\n          <div className=\"flex items-center justify-between\">\n            <p className={`text-sm ${sub}`}>{pagination.total} total</p>\n            <div className=\"flex gap-2\">\n              <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}\n                className={`p-2 rounded-xl border disabled:opacity-40 border-[var(--border)] hover:bg-[var(--bg-card)]`}>\n                <ChevronLeft size={16} className={sub} />\n              </button>\n              <button onClick={() => setPage(p => Math.min(pagination.pages, p + 1))} disabled={page === pagination.pages}\n                className={`p-2 rounded-xl border disabled:opacity-40 border-[var(--border)] hover:bg-[var(--bg-card)]`}>\n                <ChevronRight size={16} className={sub} />\n              </button>\n            </div>\n          </div>\n        )}\n      </div>\n  );\n}\n","frontend/src/app/admin/settings/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { Save, DollarSign, Package, Shield, Users } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nexport default function AdminSettingsPage() {\n  const qc   = useQueryClient();\n  const card = \"bg-[var(--bg-card)] border-[var(--border)]\";\n  const inp  = \"bg-[var(--bg-secondary)] border-[var(--border)] text-[var(--text-primary)]\";\n  const tx   = \"text-[var(--text-primary)]\";\n  const sub  = \"text-[var(--text-tertiary)]\";\n\n  const [fee, setFee]                 = useState<number>(2);\n  const [maintenance, setMaintenance] = useState(false);\n  const [allowReg, setAllowReg]       = useState(true);\n  const [feeEditing, setFeeEditing]   = useState(false);\n\n  const PLANS = [\n    { key: \"freePrice\",   name: \"Free\",   color: \"bg-[var(--bg-secondary)] text-[var(--text-tertiary)]\", value: 0 },\n    { key: \"growthPrice\", name: \"Growth\", color: \"bg-amber-400/10 text-amber-400\",                       value: 9500 },\n    { key: \"proPrice\",    name: \"Pro\",    color: \"bg-violet-400/10 text-violet-400\",                     value: 25000 },\n  ];\n\n  const { data: settings, isLoading } = useQuery({\n    queryKey: [\"admin-settings\"],\n    queryFn: async () => {\n      const r = await adminAPI.getSettings();\n      const s = r.data.data;\n      if (s.platformFeePercent !== undefined) setFee(s.platformFeePercent);\n      if (s.maintenanceMode   !== undefined) setMaintenance(s.maintenanceMode);\n      if (s.allowRegistration !== undefined) setAllowReg(s.allowRegistration);\n      return s;\n    },\n  });\n\n  const save = useMutation({\n    mutationFn: (data: any) => adminAPI.updateSettings(data),\n    onSuccess: () => { toast.success(\"Settings saved\"); qc.invalidateQueries({ queryKey: [\"admin-settings\"] }); },\n    onError:   () => toast.error(\"Save failed\"),\n  });\n\n  if (isLoading) {\n    return (\n      <div className=\"flex items-center justify-center h-64\">\n        <div className=\"w-6 h-6 rounded-full border-2 border-violet-500 border-t-transparent animate-spin\" />\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"max-w-2xl space-y-6\">\n      <div className=\"flex items-center justify-between\">\n        <div>\n          <h1 className={`text-2xl font-black tracking-tight ${tx}`}>Platform Settings</h1>\n          <p className={`text-sm mt-0.5 ${sub}`}>Changes apply platform-wide instantly</p>\n        </div>\n        <button\n          onClick={() => save.mutate({ platformFeePercent: fee, maintenanceMode: maintenance, allowRegistration: allowReg })}\n          disabled={save.isPending}\n          className=\"flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-semibold text-white disabled:opacity-50 transition-all hover:opacity-90\"\n          style={{ background: \"var(--violet-500)\" }}>\n          <Save size={14} />\n          {save.isPending ? \"Saving...\" : \"Save changes\"}\n        </button>\n      </div>\n\n      <div className={`rounded-2xl border p-6 ${card}`}>\n        <div className=\"flex items-center gap-2 mb-4\">\n          <DollarSign size={16} className=\"text-violet-500\" />\n          <h3 className={`font-bold ${tx}`}>Platform Fee</h3>\n        </div>\n        <div className=\"flex items-center justify-between\">\n          <p className={`text-sm ${sub}`}>Transaction fee charged on all orders</p>\n          {feeEditing ? (\n            <div className=\"flex items-center gap-2\">\n              <input type=\"number\" value={fee} onChange={(e) => setFee(Number(e.target.value))} min={0} max={10} step={0.5}\n                className={`w-20 px-3 py-1.5 rounded-lg text-sm border outline-none ${inp}`} />\n              <span className={`text-sm ${sub}`}>%</span>\n              <button onClick={() => setFeeEditing(false)} className=\"px-3 py-1.5 rounded-lg text-xs font-semibold text-white\" style={{ background: \"var(--violet-500)\" }}>Done</button>\n            </div>\n          ) : (\n            <div className=\"flex items-center gap-3\">\n              <span className={`text-lg font-black ${tx}`}>{fee}%</span>\n              <button onClick={() => setFeeEditing(true)} className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all hover:bg-[var(--bg-secondary)] border-[var(--border)] ${sub}`}>Edit</button>\n            </div>\n          )}\n        </div>\n      </div>\n\n      <div className={`rounded-2xl border p-6 ${card}`}>\n        <div className=\"flex items-center gap-2 mb-4\">\n          <Package size={16} className=\"text-violet-500\" />\n          <h3 className={`font-bold ${tx}`}>Subscription Plans</h3>\n        </div>\n        <div className=\"space-y-3\">\n          {PLANS.map((plan) => (\n            <div key={plan.key} className=\"flex items-center justify-between p-4 rounded-xl border border-[var(--border)]\">\n              <span className={`text-xs font-bold px-2.5 py-1 rounded-full ${plan.color}`}>{plan.name}</span>\n              <span className={`font-bold ${tx}`}>{plan.value === 0 ? \"Free\" : `N${plan.value.toLocaleString()}/mo`}</span>\n            </div>\n          ))}\n        </div>\n        <p className={`text-xs mt-3 ${sub}`}>Plan prices are managed in your Paystack dashboard.</p>\n      </div>\n\n      <div className={`rounded-2xl border p-6 ${card}`}>\n        <div className=\"flex items-center gap-2 mb-4\">\n          <Users size={16} className=\"text-violet-500\" />\n          <h3 className={`font-bold ${tx}`}>User Registration</h3>\n        </div>\n        <div className=\"flex items-center justify-between\">\n          <p className={`text-sm ${sub}`}>Allow new users to register</p>\n          <button onClick={() => setAllowReg(!allowReg)} className={`relative w-11 h-6 rounded-full transition-all ${allowReg ? \"bg-violet-500\" : \"bg-[var(--bg-secondary)]\"}`}>\n            <span className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white transition-transform ${allowReg ? \"translate-x-5\" : \"translate-x-0\"}`} />\n          </button>\n        </div>\n      </div>\n\n      <div className={`rounded-2xl border p-6 ${card}`}>\n        <div className=\"flex items-center gap-2 mb-4\">\n          <Shield size={16} className=\"text-violet-500\" />\n          <h3 className={`font-bold ${tx}`}>Maintenance Mode</h3>\n        </div>\n        <div className=\"flex items-center justify-between\">\n          <div>\n            <p className={`text-sm ${sub}`}>Take the platform offline for maintenance</p>\n            {maintenance && <p className=\"text-xs mt-1 text-amber-400\">Platform is currently in maintenance mode</p>}\n          </div>\n          <button onClick={() => setMaintenance(!maintenance)} className={`relative w-11 h-6 rounded-full transition-all ${maintenance ? \"bg-amber-500\" : \"bg-[var(--bg-secondary)]\"}`}>\n            <span className={`absolute top-0.5 left-0.5 w-5 h-5 rounded-full bg-white transition-transform ${maintenance ? \"translate-x-5\" : \"translate-x-0\"}`} />\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/admin/support/page.tsx":"\"use client\";\n\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { api, adminAPI} from \"../../../lib/api\";\n\nimport { CheckCircle, MessageSquare, ChevronDown, X } from \"lucide-react\";\nimport toast from \"react-hot-toast\";\n\nconst priorityColor: Record<string, string> = {\n  LOW: \"bg-slate-700 text-[var(--text-secondary)]\", MEDIUM: \"bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400\",\n  HIGH: \"bg-orange-100 dark:bg-orange-900/40 text-orange-700 dark:text-orange-400\", URGENT: \"bg-red-100 dark:bg-red-900/40 text-red-600 dark:text-red-400\",\n};\nconst statusColor: Record<string, string> = {\n  OPEN: \"bg-violet-100 dark:bg-violet-900/40 text-amber-700 dark:text-amber-400\", IN_PROGRESS: \"bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-400\",\n  RESOLVED: \"bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-400\", CLOSED: \"bg-slate-700 text-[var(--text-tertiary)]\",\n};\n\nexport default function AdminSupportPage() {\n  \n  \n  const qc   = useQueryClient();\n  const card = \"bg-[var(--bg-card)] border-[var(--border)]\";\n  const inp  = \"bg-[var(--bg-card)] border-[var(--border)] text-[var(--text-primary)]\";\n  const tx   = \"text-[var(--text-primary)]\";\n  const sub  = \"text-[var(--text-tertiary)]\";\n\n  const [expand, setExpand] = useState<string | null>(null);\n  const [reply, setReply]   = useState(\"\");\n  const [filter, setFilter] = useState(\"OPEN\");\n\n  const { data, isLoading } = useQuery({\n    queryKey: [\"admin-tickets\", filter],\n    queryFn:  () => adminAPI.getTickets({ status: filter || undefined }).then((r) => r.data.data),\n  });\n\n  const resolveMut = useMutation({\n    mutationFn: ({ id, msg }: { id: string; msg: string }) =>\n      adminAPI.updateTicket(id, { status: \"RESOLVED\", message: msg }),\n    onSuccess: () => { toast.success(\"Ticket resolved\"); qc.invalidateQueries({ queryKey: [\"admin-tickets\"] }); setExpand(null); setReply(\"\"); },\n    onError:   () => toast.error(\"Failed to resolve\"),\n  });\n\n  const replyMut = useMutation({\n    mutationFn: ({ id, msg }: { id: string; msg: string }) =>\n      adminAPI.updateTicket(id, { status: \"IN_PROGRESS\", message: msg }),\n    onSuccess: () => { toast.success(\"Reply sent\"); qc.invalidateQueries({ queryKey: [\"admin-tickets\"] }); setReply(\"\"); },\n    onError:   () => toast.error(\"Failed to send reply\"),\n  });\n\n  const tickets = data || [];\n\n  return (\n      <div className=\"space-y-6 max-w-3xl\">\n        <div>\n          <h1 className={`text-2xl font-black tracking-tight ${tx}`}>Support Tickets</h1>\n          <p className={`text-sm mt-0.5 ${sub}`}>{tickets.length} {filter.toLowerCase()} tickets</p>\n        </div>\n\n        {/* Filter */}\n        <div className=\"flex gap-2\">\n          {[[\"OPEN\", \"Open\"], [\"IN_PROGRESS\", \"In Progress\"], [\"RESOLVED\", \"Resolved\"], [\"\", \"All\"]].map(([v, l]) => (\n            <button key={v} onClick={() => setFilter(v)}\n              className={`px-3 py-2 rounded-xl text-xs font-semibold transition-all\n                ${filter === v ? \"text-[var(--text-primary)]\" : `${sub} ${\"hover:bg-[var(--bg-card)]\"}`}`}\n              style={filter === v ? { background: \"linear-gradient(135deg,#7c3aed,#a855f7)\" } : {}}>\n              {l}\n            </button>\n          ))}\n        </div>\n\n        {/* Tickets */}\n        {isLoading ? (\n          <div className=\"space-y-3\">\n            {[1, 2, 3].map((i) => (\n              <div key={i} className={`rounded-2xl border p-5 animate-pulse ${card}`}>\n                <div className={`h-4 w-64 rounded mb-2 ${\"bg-[var(--bg-card)]\"}`} />\n                <div className={`h-3 w-40 rounded ${\"bg-[var(--bg-card)]\"}`} />\n              </div>\n            ))}\n          </div>\n        ) : tickets.length === 0 ? (\n          <div className={`text-center py-12 ${sub}`}>\n            <MessageSquare size={40} className=\"mx-auto mb-3 opacity-20\" />\n            <p>No {filter.toLowerCase()} tickets</p>\n          </div>\n        ) : (\n          <div className=\"space-y-3\">\n            {tickets.map((t: any) => (\n              <div key={t.id} className={`rounded-2xl border overflow-hidden ${card}`}>\n                <button className=\"w-full text-left p-5\" onClick={() => setExpand(expand === t.id ? null : t.id)}>\n                  <div className=\"flex items-start justify-between gap-3\">\n                    <div className=\"flex-1\">\n                      <div className={`font-bold ${tx}`}>{t.subject}</div>\n                      <div className={`text-xs mt-1 ${sub}`}>\n                        From <strong className={\"text-[var(--text-secondary)]\"}>{t.user?.name}</strong>\n                        {\" \"}({t.user?.email}) · {new Date(t.createdAt).toLocaleDateString()}\n                      </div>\n                    </div>\n                    <div className=\"flex items-center gap-2 flex-shrink-0\">\n                      <span className={`text-xs font-bold px-2.5 py-1 rounded-full ${priorityColor[t.priority]}`}>{t.priority}</span>\n                      <span className={`text-xs font-bold px-2.5 py-1 rounded-full ${statusColor[t.status]}`}>{t.status.replace(\"_\", \" \")}</span>\n                      <ChevronDown size={14} className={`${sub} transition-transform ${expand === t.id ? \"rotate-180\" : \"\"}`} />\n                    </div>\n                  </div>\n                </button>\n\n                {expand === t.id && (\n                  <div className={`px-5 pb-5 border-t border-[var(--border)]/50`}>\n                    <div className={`mt-4 rounded-xl p-4 border text-sm bg-[#08080f] border-[var(--border)]`}>\n                      <div className={`text-xs font-semibold ${sub} mb-1`}>Message</div>\n                      <p className={tx}>{t.message}</p>\n                    </div>\n\n                    {t.adminReply && (\n                      <div className=\"mt-3 rounded-xl p-4 border border-violet-500/20 text-sm\"\n                        style={{ background: \"rgba(124,58,237,.08)\" }}>\n                        <div className=\"text-xs font-semibold text-amber-700 dark:text-amber-400 mb-1 flex items-center gap-1.5\">\n                          <CheckCircle size={11} /> Previous Reply\n                        </div>\n                        <p className={tx}>{t.adminReply}</p>\n                      </div>\n                    )}\n\n                    {t.status !== \"RESOLVED\" && (\n                      <div className=\"mt-4 space-y-3\">\n                        <textarea value={reply} onChange={(e) => setReply(e.target.value)}\n                          rows={3} placeholder=\"Write your reply…\"\n                          className={`w-full rounded-xl px-3 py-2.5 text-sm border outline-none focus:border-violet-500 resize-none transition-all ${inp}`} />\n                        <div className=\"flex gap-2\">\n                          <button\n                            onClick={() => { if (reply.trim()) replyMut.mutate({ id: t.id, msg: reply }); }}\n                            disabled={!reply.trim() || replyMut.isPending}\n                            className={`flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-bold border transition-all\n                              border-violet-500/30 text-amber-700 dark:text-amber-400 hover:bg-amber-400/10 disabled:opacity-40`}>\n                            <MessageSquare size={12} /> Send Reply\n                          </button>\n                          <button\n                            onClick={() => resolveMut.mutate({ id: t.id, msg: reply || \"Your issue has been resolved. Please reach out if you need further assistance.\" })}\n                            disabled={resolveMut.isPending}\n                            className=\"flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-bold bg-emerald-600 text-[var(--text-primary)] hover:bg-emerald-500 disabled:opacity-60\">\n                            <CheckCircle size={12} /> Mark Resolved\n                          </button>\n                        </div>\n                      </div>\n                    )}\n                  </div>\n                )}\n              </div>\n            ))}\n          </div>\n        )}\n      </div>\n  );\n}\n","frontend/src/app/admin/growth/page.tsx":"\"use client\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from \"recharts\";\nimport { TrendingUp, Users, DollarSign, Zap, ArrowUpRight, Percent } from \"lucide-react\";\nimport { PageHeader, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\nimport { motion } from \"framer-motion\";\n\nconst V = { accent:\"#6B35E8\", v400:\"#8B5CF6\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nfunction fmtCurrency(n: number) {\n  if (n >= 1_000_000) return `₦${(n/1_000_000).toFixed(2)}M`;\n  if (n >= 1_000)     return `₦${(n/1_000).toFixed(1)}k`;\n  return `₦${n.toFixed(0)}`;\n}\n\nfunction MetricCard({ label, value, sub, color, icon:Icon, delay=0 }: any) {\n  return (\n    <motion.div initial={{ opacity:0,y:12 }} animate={{ opacity:1,y:0 }} transition={{ delay }}\n      style={{ padding:24, borderRadius:18, background:t.card, border:`1px solid ${t.border}` }}>\n      <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:16 }}>\n        <div style={{ width:38, height:38, borderRadius:11, background:`${color}14`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n          <Icon size={17} color={color}/>\n        </div>\n        {sub && <span style={{ fontSize:11, fontWeight:700, color:V.green, background:\"rgba(16,185,129,0.1)\", padding:\"2px 8px\", borderRadius:99, display:\"flex\", alignItems:\"center\", gap:3 }}>\n          <ArrowUpRight size={10}/>{sub}\n        </span>}\n      </div>\n      <p style={{ fontSize:28, fontWeight:900, color:t.text, letterSpacing:\"-0.05em\", margin:\"0 0 4px\", lineHeight:1 }}>{value}</p>\n      <p style={{ fontSize:12, color:t.muted, margin:0 }}>{label}</p>\n    </motion.div>\n  );\n}\n\nexport default function AdminGrowthPage() {\n  const { data: raw } = useQuery<any>({\n    queryKey: [\"admin-growth\"],\n    queryFn: () => adminAPI.get(\"/admin/growth\").then((r:any) => r.data.data),\n    refetchInterval: 300_000,\n  });\n  const { data: statsRaw } = useQuery<any>({\n    queryKey: [\"admin-overview\"],\n    queryFn: () => adminAPI.getStats().then((r:any) => r.data.data),\n  });\n\n  const g = raw || {};\n  const s = statsRaw || {};\n  const monthly = s.monthlyRevenue || [];\n\n  return (\n    <div>\n      <PageHeader title=\"Growth Metrics\" sub=\"MRR, ARR, LTV and platform health\"/>\n\n      {/* Key Metrics */}\n      <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:12, marginBottom:24 }} className=\"adm-3col\">\n        <MetricCard label=\"Monthly Recurring Revenue (MRR)\" value={fmtCurrency(g.MRR||0)} color={V.green} icon={DollarSign} delay={0}/>\n        <MetricCard label=\"Annual Run Rate (ARR)\"           value={fmtCurrency(g.ARR||0)} color={V.accent} icon={TrendingUp} delay={0.07}/>\n        <MetricCard label=\"Avg Lifetime Value (LTV)\"       value={fmtCurrency(g.LTV||0)} color={V.cyan}   icon={Zap}        delay={0.14}/>\n      </div>\n\n      <StatGrid cols={4}>\n        <StatCard label=\"Total merchants\"   value={(g.totalUsers||0).toLocaleString()}             color={V.accent} icon={Users}/>\n        <StatCard label=\"Paying merchants\"  value={(g.paidUsers||0).toLocaleString()}              color={V.green}  icon={Users}/>\n        <StatCard label=\"ARPU\"              value={fmtCurrency(g.ARPU||0)}                         color={V.amber}  icon={DollarSign}/>\n        <StatCard label=\"Free → Paid rate\"  value={`${g.convRate||0}%`}                            color={V.cyan}   icon={Percent}/>\n      </StatGrid>\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }} className=\"adm-2col\">\n        {/* Revenue trend */}\n        <motion.div initial={{ opacity:0,y:12 }} animate={{ opacity:1,y:0 }} transition={{ delay:0.2 }}\n          style={{ background:t.card, borderRadius:18, padding:24, border:`1px solid ${t.border}` }}>\n          <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:\"0 0 4px\" }}>Platform fee revenue</p>\n          <p style={{ fontSize:12, color:t.muted, margin:\"0 0 20px\" }}>Monthly DropOS earnings from transaction fees</p>\n          <div style={{ height:200 }}>\n            <ResponsiveContainer width=\"100%\" height=\"100%\">\n              <AreaChart data={monthly} margin={{ top:0,right:0,left:-20,bottom:0 }}>\n                <defs>\n                  <linearGradient id=\"gr\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                    <stop offset=\"5%\"  stopColor={V.green} stopOpacity={0.3}/>\n                    <stop offset=\"95%\" stopColor={V.green} stopOpacity={0}/>\n                  </linearGradient>\n                </defs>\n                <XAxis dataKey=\"month\" tick={{ fill:\"rgba(255,255,255,0.3)\",fontSize:11 }} axisLine={false} tickLine={false}/>\n                <YAxis tickFormatter={v=>`₦${(v/1000).toFixed(0)}k`} tick={{ fill:\"rgba(255,255,255,0.3)\",fontSize:11 }} axisLine={false} tickLine={false}/>\n                <Tooltip contentStyle={{ background:\"#0d0a1a\",border:\"1px solid rgba(255,255,255,0.1)\",borderRadius:10,fontSize:12 }} formatter={(v:any)=>[`₦${Number(v).toLocaleString()}`,\"\"]}/>\n                <Area type=\"monotone\" dataKey=\"fees\" stroke={V.green} fill=\"url(#gr)\" strokeWidth={2} name=\"DropOS Fees\"/>\n              </AreaChart>\n            </ResponsiveContainer>\n          </div>\n        </motion.div>\n\n        {/* Weekly new users */}\n        <motion.div initial={{ opacity:0,y:12 }} animate={{ opacity:1,y:0 }} transition={{ delay:0.25 }}\n          style={{ background:t.card, borderRadius:18, padding:24, border:`1px solid ${t.border}` }}>\n          <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:\"0 0 4px\" }}>New merchants (weekly)</p>\n          <p style={{ fontSize:12, color:t.muted, margin:\"0 0 20px\" }}>Signups over the last 8 weeks</p>\n          <div style={{ height:200 }}>\n            <ResponsiveContainer width=\"100%\" height=\"100%\">\n              <BarChart data={g.weeklyGrowth||[]} margin={{ top:0,right:0,left:-20,bottom:0 }}>\n                <XAxis dataKey=\"week\" tick={{ fill:\"rgba(255,255,255,0.3)\",fontSize:11 }} axisLine={false} tickLine={false}/>\n                <YAxis tick={{ fill:\"rgba(255,255,255,0.3)\",fontSize:11 }} axisLine={false} tickLine={false}/>\n                <Tooltip contentStyle={{ background:\"#0d0a1a\",border:\"1px solid rgba(255,255,255,0.1)\",borderRadius:10,fontSize:12 }}/>\n                <Bar dataKey=\"newUsers\" fill={V.accent} radius={[4,4,0,0]} name=\"New merchants\"/>\n              </BarChart>\n            </ResponsiveContainer>\n          </div>\n        </motion.div>\n      </div>\n\n      <style>{`\n        @media(max-width:900px){ .adm-3col{grid-template-columns:1fr 1fr!important;} .adm-2col{grid-template-columns:1fr!important;} }\n        @media(max-width:480px){ .adm-3col{grid-template-columns:1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/churn/page.tsx":"\"use client\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from \"recharts\";\nimport { UserMinus, AlertTriangle, TrendingDown, RefreshCw } from \"lucide-react\";\nimport { PageHeader, StatGrid, StatCard } from \"../../../components/admin/AdminTable\";\nimport { motion } from \"framer-motion\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\", cyan:\"#06B6D4\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nexport default function AdminChurnPage() {\n  const { data:raw, isLoading } = useQuery<any>({\n    queryKey: [\"admin-churn\"],\n    queryFn: () => adminAPI.get(\"/admin/churn\").then((r:any) => r.data.data),\n  });\n\n  const c = raw || {};\n\n  const actionItems = [\n    { icon:\"📧\", title:\"Send win-back campaign\", desc:`${c.atRisk||0} stores have had no orders in 14+ days. Broadcast a flash sale nudge.`, color:V.amber, urgent: (c.atRisk||0) > 0 },\n    { icon:\"💰\", title:\"Offer downgrade incentive\", desc:`${c.recentCancels||0} merchants switched to Free this month. Send a 30% discount offer to win them back.`, color:V.accent, urgent: (c.recentCancels||0) > 0 },\n    { icon:\"📞\", title:\"Manual outreach\", desc:`${c.churned||0} accounts suspended in last 30 days. Review and reach out to high-value ones.`, color:V.red, urgent: (c.churned||0) > 3 },\n  ];\n\n  return (\n    <div>\n      <PageHeader title=\"Churn Analysis\" sub=\"Merchant retention and at-risk account tracking\"/>\n\n      <StatGrid cols={4}>\n        <StatCard label=\"Churned (30d)\"     value={c.churned||0}       color={V.red}   icon={UserMinus} sub={-(c.churnRate||0)}/>\n        <StatCard label=\"At-risk stores\"    value={c.atRisk||0}        color={V.amber} icon={AlertTriangle}/>\n        <StatCard label=\"Recent downgrades\" value={c.recentCancels||0} color={V.accent} icon={TrendingDown}/>\n        <StatCard label=\"Churn rate\"        value={`${c.churnRate||0}%`} color={V.red}  icon={RefreshCw}/>\n      </StatGrid>\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12, marginBottom:16 }} className=\"adm-2col\">\n        {/* Monthly churn chart */}\n        <motion.div initial={{ opacity:0,y:12 }} animate={{ opacity:1,y:0 }} transition={{ delay:0.15 }}\n          style={{ background:t.card, borderRadius:18, padding:24, border:`1px solid ${t.border}` }}>\n          <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:\"0 0 4px\" }}>Monthly churn</p>\n          <p style={{ fontSize:12, color:t.muted, margin:\"0 0 18px\" }}>Suspended accounts per month</p>\n          <div style={{ height:200 }}>\n            <ResponsiveContainer width=\"100%\" height=\"100%\">\n              <BarChart data={c.monthlyChurn||[]} margin={{ top:0,right:0,left:-20,bottom:0 }}>\n                <XAxis dataKey=\"month\" tick={{ fill:\"rgba(255,255,255,0.3)\",fontSize:11 }} axisLine={false} tickLine={false}/>\n                <YAxis tick={{ fill:\"rgba(255,255,255,0.3)\",fontSize:11 }} axisLine={false} tickLine={false} allowDecimals={false}/>\n                <Tooltip contentStyle={{ background:\"#0d0a1a\",border:\"1px solid rgba(255,255,255,0.1)\",borderRadius:10,fontSize:12 }}/>\n                <Bar dataKey=\"churned\" fill={V.red} radius={[4,4,0,0]} name=\"Churned\"/>\n              </BarChart>\n            </ResponsiveContainer>\n          </div>\n        </motion.div>\n\n        {/* Action items */}\n        <motion.div initial={{ opacity:0,y:12 }} animate={{ opacity:1,y:0 }} transition={{ delay:0.2 }}\n          style={{ background:t.card, borderRadius:18, padding:24, border:`1px solid ${t.border}` }}>\n          <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:\"0 0 18px\" }}>Recommended actions</p>\n          <div style={{ display:\"flex\", flexDirection:\"column\", gap:10 }}>\n            {actionItems.map((a, i) => (\n              <div key={i} style={{ padding:\"14px 16px\", borderRadius:12, background:a.urgent?`${a.color}08`:\"rgba(255,255,255,0.02)\", border:`1px solid ${a.urgent?`${a.color}20`:\"rgba(255,255,255,0.05)\"}` }}>\n                <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:5 }}>\n                  <span style={{ fontSize:18 }}>{a.icon}</span>\n                  <p style={{ fontSize:13, fontWeight:700, color:a.urgent?t.text:\"rgba(255,255,255,0.5)\", margin:0 }}>{a.title}</p>\n                  {a.urgent && <span style={{ fontSize:9, fontWeight:800, padding:\"2px 6px\", borderRadius:99, background:`${a.color}20`, color:a.color, textTransform:\"uppercase\", letterSpacing:\"0.05em\", marginLeft:\"auto\" }}>Action needed</span>}\n                </div>\n                <p style={{ fontSize:12, color:t.muted, margin:0, lineHeight:1.5 }}>{a.desc}</p>\n              </div>\n            ))}\n          </div>\n        </motion.div>\n      </div>\n\n      <style>{`@media(max-width:768px){ .adm-2col{grid-template-columns:1fr!important;} }`}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/coupons/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Tag, Plus, Trash2, X, Check } from \"lucide-react\";\nimport { PageHeader, DataTable, Badge, Pagination } from \"../../../components/admin/AdminTable\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\", red:\"#EF4444\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\nconst inp: any = { width:\"100%\", padding:\"10px 14px\", borderRadius:11, border:\"1px solid rgba(255,255,255,0.09)\", background:\"rgba(255,255,255,0.05)\", color:\"rgba(255,255,255,0.9)\", fontSize:13, fontFamily:\"inherit\", outline:\"none\" };\n\nexport default function AdminCouponsPage() {\n  const qc = useQueryClient();\n  const [page, setPage]   = useState(1);\n  const [showing, setShowing] = useState(false);\n  const [form, setForm] = useState({ code:\"\", type:\"PERCENTAGE\", value:\"\", maxUses:\"\", expiresAt:\"\", description:\"\", targetPlan:\"\" });\n\n  const { data, isLoading } = useQuery<any>({\n    queryKey: [\"admin-coupons\", page],\n    queryFn: () => adminAPI.get(\"/admin/coupons\", { params:{ page, limit:20 } }).then((r:any) => r.data),\n  });\n\n  const createMut = useMutation({\n    mutationFn: () => adminAPI.post(\"/admin/coupons\", form),\n    onSuccess: () => { toast.success(\"Coupon created!\"); qc.invalidateQueries({ queryKey:[\"admin-coupons\"] }); setShowing(false); setForm({ code:\"\", type:\"PERCENTAGE\", value:\"\", maxUses:\"\", expiresAt:\"\", description:\"\", targetPlan:\"\" }); },\n    onError: (e:any) => toast.error(e.response?.data?.error||\"Failed\"),\n  });\n  const deleteMut = useMutation({\n    mutationFn: (id:string) => adminAPI.delete(`/admin/coupons/${id}`),\n    onSuccess: () => { toast.success(\"Deleted\"); qc.invalidateQueries({ queryKey:[\"admin-coupons\"] }); },\n  });\n\n  const coupons = data?.data || [];\n  const meta    = data?.pagination || { total:0, pages:1 };\n\n  const rows = coupons.map((c: any) => ({\n    code:        <span style={{ fontSize:13, fontWeight:800, fontFamily:\"monospace\", color:\"#A78BFA\", letterSpacing:\"0.05em\" }}>{c.code}</span>,\n    type:        <Badge label={c.type} color={c.type===\"PERCENTAGE\"?V.amber:V.green} bg={c.type===\"PERCENTAGE\"?\"rgba(245,158,11,0.1)\":\"rgba(16,185,129,0.1)\"}/>,\n    value:       <span style={{ fontSize:13, fontWeight:700, color:t.text }}>{c.type===\"PERCENTAGE\"?`${c.value}%`:`₦${Number(c.value).toLocaleString()}`} off</span>,\n    usage:       <span style={{ fontSize:12, color:t.muted }}>{c.usedCount||0}{c.maxUses?`/${c.maxUses}`:\"\"} uses</span>,\n    target:      <span style={{ fontSize:12, color:t.muted }}>{c.targetPlan||\"All plans\"}</span>,\n    expires:     <span style={{ fontSize:11, color:c.expiresAt&&new Date(c.expiresAt)<new Date()?V.red:t.muted }}>{c.expiresAt?new Date(c.expiresAt).toLocaleDateString(\"en-NG\",{day:\"numeric\",month:\"short\",year:\"2-digit\"}):\"Never\"}</span>,\n    status:      <Badge label={c.isActive?\"ACTIVE\":\"INACTIVE\"} color={c.isActive?V.green:\"rgba(255,255,255,0.3)\"} bg={c.isActive?\"rgba(16,185,129,0.1)\":\"rgba(255,255,255,0.05)\"}/>,\n    del:         (\n      <button onClick={() => { if(confirm(`Delete ${c.code}?`)) deleteMut.mutate(c.id); }}\n        style={{ padding:\"5px 8px\", borderRadius:7, background:\"rgba(239,68,68,0.07)\", border:\"1px solid rgba(239,68,68,0.12)\", color:V.red, cursor:\"pointer\", display:\"flex\", alignItems:\"center\" }}>\n        <Trash2 size={11}/>\n      </button>\n    ),\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Platform Coupons\" sub=\"Promo codes for merchant onboarding and campaigns\"\n        action={\n          <button onClick={() => setShowing(true)}\n            style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"9px 16px\", borderRadius:10, border:\"none\", cursor:\"pointer\", background:V.accent, color:\"#fff\", fontSize:13, fontWeight:700, fontFamily:\"inherit\" }}>\n            <Plus size={13}/> New coupon\n          </button>\n        }/>\n\n      <DataTable loading={isLoading}\n        cols={[\n          { key:\"code\",    label:\"Code\",     width:\"130px\"         },\n          { key:\"type\",    label:\"Type\",     width:\"110px\"         },\n          { key:\"value\",   label:\"Value\",    width:\"100px\"         },\n          { key:\"usage\",   label:\"Usage\",    width:\"90px\", hide:\"sm\" },\n          { key:\"target\",  label:\"Target\",   width:\"90px\", hide:\"md\" },\n          { key:\"expires\", label:\"Expires\",  width:\"90px\", hide:\"sm\" },\n          { key:\"status\",  label:\"Status\",   width:\"90px\"          },\n          { key:\"del\",     label:\"\",         width:\"40px\"          },\n        ]}\n        rows={rows} empty=\"No coupons yet — create your first one\"/>\n      <Pagination page={page} pages={meta.pages||1} total={meta.total||0} onPage={setPage}/>\n\n      {/* Create modal */}\n      <AnimatePresence>\n        {showing && (\n          <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}\n            style={{ position:\"fixed\", inset:0, background:\"rgba(0,0,0,0.7)\", zIndex:100, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", padding:24 }}>\n            <motion.div initial={{ scale:0.95,y:20 }} animate={{ scale:1,y:0 }} exit={{ scale:0.95,y:20 }}\n              style={{ background:\"#0d0a1a\", borderRadius:20, padding:28, border:`1px solid ${t.border}`, width:\"100%\", maxWidth:500, maxHeight:\"90vh\", overflowY:\"auto\" }}>\n              <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", marginBottom:22 }}>\n                <h2 style={{ fontSize:18, fontWeight:800, color:t.text, margin:0, letterSpacing:\"-0.03em\" }}>Create coupon</h2>\n                <button onClick={() => setShowing(false)} style={{ background:\"none\", border:\"none\", cursor:\"pointer\", color:t.muted, padding:4 }}><X size={16}/></button>\n              </div>\n              <div style={{ display:\"flex\", flexDirection:\"column\", gap:14 }}>\n                <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }}>\n                  <div>\n                    <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Code</label>\n                    <input value={form.code} onChange={e=>setForm(f=>({...f,code:e.target.value.toUpperCase()}))} placeholder=\"LAUNCH50\" style={inp}/>\n                  </div>\n                  <div>\n                    <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Type</label>\n                    <select value={form.type} onChange={e=>setForm(f=>({...f,type:e.target.value}))} style={{ ...inp }}>\n                      <option value=\"PERCENTAGE\">Percentage (%)</option>\n                      <option value=\"FIXED\">Fixed amount (₦)</option>\n                    </select>\n                  </div>\n                </div>\n                <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }}>\n                  <div>\n                    <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Value ({form.type===\"PERCENTAGE\"?\"%\":\"₦\"})</label>\n                    <input type=\"number\" value={form.value} onChange={e=>setForm(f=>({...f,value:e.target.value}))} placeholder={form.type===\"PERCENTAGE\"?\"30\":\"5000\"} style={inp}/>\n                  </div>\n                  <div>\n                    <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Max uses</label>\n                    <input type=\"number\" value={form.maxUses} onChange={e=>setForm(f=>({...f,maxUses:e.target.value}))} placeholder=\"Unlimited\" style={inp}/>\n                  </div>\n                </div>\n                <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }}>\n                  <div>\n                    <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Target plan</label>\n                    <select value={form.targetPlan} onChange={e=>setForm(f=>({...f,targetPlan:e.target.value}))} style={{ ...inp }}>\n                      <option value=\"\">All plans</option>\n                      <option value=\"FREE\">Free only</option>\n                      <option value=\"GROWTH\">Growth only</option>\n                      <option value=\"PRO\">Pro only</option>\n                    </select>\n                  </div>\n                  <div>\n                    <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Expires</label>\n                    <input type=\"date\" value={form.expiresAt} onChange={e=>setForm(f=>({...f,expiresAt:e.target.value}))} style={inp}/>\n                  </div>\n                </div>\n                <div>\n                  <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:6 }}>Description (internal)</label>\n                  <input value={form.description} onChange={e=>setForm(f=>({...f,description:e.target.value}))} placeholder=\"e.g. Launch campaign Q2 2026\" style={inp}/>\n                </div>\n                <div style={{ display:\"flex\", gap:10, marginTop:4 }}>\n                  <button onClick={() => setShowing(false)}\n                    style={{ flex:1, padding:\"11px 0\", borderRadius:11, border:`1px solid ${t.border}`, background:\"transparent\", color:t.muted, cursor:\"pointer\", fontSize:13, fontWeight:700, fontFamily:\"inherit\" }}>\n                    Cancel\n                  </button>\n                  <button onClick={() => createMut.mutate()} disabled={!form.code||!form.value||createMut.isPending}\n                    style={{ flex:1, padding:\"11px 0\", borderRadius:11, border:\"none\", cursor:\"pointer\", background:V.accent, color:\"#fff\", fontSize:13, fontWeight:700, fontFamily:\"inherit\", opacity:(!form.code||!form.value)?0.5:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:6 }}>\n                    {createMut.isPending?\"Creating...\":<><Check size={13}/> Create coupon</>}\n                  </button>\n                </div>\n              </div>\n            </motion.div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n}\n","frontend/src/app/admin/email-templates/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport { useQuery, useMutation, useQueryClient } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { motion } from \"framer-motion\";\nimport { Mail, Save, Eye, EyeOff } from \"lucide-react\";\nimport { PageHeader } from \"../../../components/admin/AdminTable\";\nimport toast from \"react-hot-toast\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\" };\nconst t = { card:\"rgba(255,255,255,0.03)\", border:\"rgba(255,255,255,0.07)\", text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nconst TEMPLATE_LABELS: Record<string,{ label:string; desc:string; vars:string[] }> = {\n  welcome:       { label:\"Welcome email\",        desc:\"Sent when a new merchant signs up\", vars:[\"{{name}}\",\"{{storeName}}\",\"{{ctaUrl}}\"] },\n  orderConfirm:  { label:\"Order confirmed\",       desc:\"Sent to customer when order is placed\", vars:[\"{{customerName}}\",\"{{storeName}}\",\"{{orderNumber}}\",\"{{total}}\",\"{{deliveryDate}}\",\"{{trackingUrl}}\"] },\n  orderShipped:  { label:\"Order shipped\",         desc:\"Sent when order status becomes SHIPPED\", vars:[\"{{customerName}}\",\"{{orderNumber}}\",\"{{storeName}}\",\"{{trackingUrl}}\"] },\n  passwordReset: { label:\"Password reset\",        desc:\"Sent when merchant requests password reset\", vars:[\"{{name}}\",\"{{resetUrl}}\"] },\n  planUpgraded:  { label:\"Plan upgrade\",          desc:\"Sent when merchant upgrades their plan\", vars:[\"{{name}}\",\"{{plan}}\",\"{{dashboardUrl}}\"] },\n};\n\nexport default function AdminEmailTemplatesPage() {\n  const qc = useQueryClient();\n  const [active, setActive] = useState(\"welcome\");\n  const [preview, setPreview] = useState(false);\n  const [form, setForm] = useState<Record<string,{subject:string;body:string}>>({});\n\n  const { data:raw } = useQuery<any>({\n    queryKey: [\"admin-email-templates\"],\n    queryFn: () => adminAPI.get(\"/admin/email-templates\").then((r:any) => r.data.data),\n  });\n\n  useEffect(() => { if (raw) setForm(raw); }, [raw]);\n\n  const saveMut = useMutation({\n    mutationFn: () => adminAPI.patch(\"/admin/email-templates\", { key:active, ...form[active] }),\n    onSuccess: () => { toast.success(\"Template saved\"); qc.invalidateQueries({ queryKey:[\"admin-email-templates\"] }); },\n    onError:   () => toast.error(\"Save failed\"),\n  });\n\n  const current = form[active] || { subject:\"\", body:\"\" };\n  const meta    = TEMPLATE_LABELS[active];\n\n  return (\n    <div>\n      <PageHeader title=\"Email Templates\" sub=\"Edit the transactional emails sent to merchants and customers\"\n        action={\n          <div style={{ display:\"flex\", gap:8 }}>\n            <button onClick={() => setPreview(p => !p)}\n              style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"9px 14px\", borderRadius:10, border:`1px solid ${t.border}`, background:\"transparent\", color:t.muted, cursor:\"pointer\", fontSize:13, fontWeight:600, fontFamily:\"inherit\" }}>\n              {preview ? <EyeOff size={13}/> : <Eye size={13}/>} {preview?\"Edit\":\"Preview\"}\n            </button>\n            <button onClick={() => saveMut.mutate()} disabled={saveMut.isPending}\n              style={{ display:\"flex\", alignItems:\"center\", gap:6, padding:\"9px 16px\", borderRadius:10, border:\"none\", cursor:\"pointer\", background:V.accent, color:\"#fff\", fontSize:13, fontWeight:700, fontFamily:\"inherit\" }}>\n              <Save size={13}/> {saveMut.isPending?\"Saving...\":\"Save\"}\n            </button>\n          </div>\n        }/>\n\n      <div style={{ display:\"grid\", gridTemplateColumns:\"220px 1fr\", gap:12 }} className=\"adm-2col\">\n        {/* Template list */}\n        <div style={{ background:t.card, borderRadius:16, border:`1px solid ${t.border}`, padding:8, height:\"fit-content\" }}>\n          {Object.entries(TEMPLATE_LABELS).map(([key, meta]) => (\n            <button key={key} onClick={() => { setActive(key); setPreview(false); }}\n              style={{ width:\"100%\", textAlign:\"left\", padding:\"10px 12px\", borderRadius:10, border:\"none\", cursor:\"pointer\", fontFamily:\"inherit\", background:active===key?\"rgba(107,53,232,0.12)\":\"transparent\", marginBottom:2, transition:\"background 0.15s\" }}>\n              <p style={{ fontSize:13, fontWeight:active===key?700:500, color:active===key?\"#fff\":t.muted, margin:0 }}>{meta.label}</p>\n            </button>\n          ))}\n        </div>\n\n        {/* Editor / Preview */}\n        <motion.div key={active+preview} initial={{ opacity:0,y:8 }} animate={{ opacity:1,y:0 }}\n          style={{ background:t.card, borderRadius:16, border:`1px solid ${t.border}`, padding:24 }}>\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:10, marginBottom:20, paddingBottom:16, borderBottom:`1px solid rgba(255,255,255,0.06)` }}>\n            <div style={{ width:32, height:32, borderRadius:9, background:\"rgba(107,53,232,0.12)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n              <Mail size={14} color={V.accent}/>\n            </div>\n            <div>\n              <p style={{ fontSize:14, fontWeight:700, color:t.text, margin:0 }}>{meta?.label}</p>\n              <p style={{ fontSize:11, color:t.muted, margin:0 }}>{meta?.desc}</p>\n            </div>\n          </div>\n\n          {preview ? (\n            <div style={{ background:\"#fff\", borderRadius:12, padding:28, color:\"#1a1a2e\" }}>\n              <div style={{ borderBottom:\"1px solid #eee\", paddingBottom:16, marginBottom:20 }}>\n                <p style={{ fontSize:11, color:\"#888\", margin:\"0 0 4px\" }}>SUBJECT</p>\n                <p style={{ fontSize:16, fontWeight:600, color:\"#1a1a2e\", margin:0 }}>{current.subject}</p>\n              </div>\n              <pre style={{ fontFamily:\"system-ui,sans-serif\", fontSize:14, color:\"#333\", whiteSpace:\"pre-wrap\", lineHeight:1.7, margin:0 }}>{current.body}</pre>\n            </div>\n          ) : (\n            <div style={{ display:\"flex\", flexDirection:\"column\", gap:14 }}>\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Subject line</label>\n                <input value={current.subject} onChange={e => setForm(f => ({ ...f, [active]:{ ...f[active], subject:e.target.value } }))}\n                  style={{ width:\"100%\", padding:\"11px 14px\", borderRadius:11, border:\"1px solid rgba(255,255,255,0.09)\", background:\"rgba(255,255,255,0.05)\", color:t.text, fontSize:13, fontFamily:\"inherit\", outline:\"none\" }}/>\n              </div>\n              <div>\n                <label style={{ fontSize:12, fontWeight:700, color:t.muted, display:\"block\", marginBottom:7 }}>Body</label>\n                <textarea value={current.body} rows={14}\n                  onChange={e => setForm(f => ({ ...f, [active]:{ ...f[active], body:e.target.value } }))}\n                  style={{ width:\"100%\", padding:\"11px 14px\", borderRadius:11, border:\"1px solid rgba(255,255,255,0.09)\", background:\"rgba(255,255,255,0.05)\", color:t.text, fontSize:13, fontFamily:\"monospace\", outline:\"none\", resize:\"vertical\", lineHeight:1.7 }}/>\n              </div>\n              {meta?.vars && (\n                <div style={{ padding:\"12px 14px\", borderRadius:10, background:\"rgba(107,53,232,0.06)\", border:\"1px solid rgba(107,53,232,0.12)\" }}>\n                  <p style={{ fontSize:11, fontWeight:700, color:\"rgba(167,139,250,0.7)\", margin:\"0 0 8px\", textTransform:\"uppercase\", letterSpacing:\"0.08em\" }}>Available variables</p>\n                  <div style={{ display:\"flex\", flexWrap:\"wrap\", gap:6 }}>\n                    {meta.vars.map(v => (\n                      <code key={v} style={{ fontSize:11, padding:\"2px 8px\", borderRadius:6, background:\"rgba(107,53,232,0.15)\", color:\"#A78BFA\" }}>{v}</code>\n                    ))}\n                  </div>\n                </div>\n              )}\n            </div>\n          )}\n        </motion.div>\n      </div>\n      <style>{`@media(max-width:768px){ .adm-2col{grid-template-columns:1fr!important;} }`}</style>\n    </div>\n  );\n}\n","frontend/src/app/admin/paystack/page.tsx":"\"use client\";\nimport { useQuery } from \"@tanstack/react-query\";\nimport { adminAPI } from \"../../../lib/api\";\nimport { ExternalLink, Building2 } from \"lucide-react\";\nimport { PageHeader, DataTable } from \"../../../components/admin/AdminTable\";\n\nconst V = { accent:\"#6B35E8\", green:\"#10B981\", amber:\"#F59E0B\" };\nconst t = { text:\"rgba(255,255,255,0.9)\", muted:\"rgba(255,255,255,0.4)\" };\n\nexport default function AdminPaystackPage() {\n  const { data:raw, isLoading } = useQuery<any>({\n    queryKey: [\"admin-paystack-subs\"],\n    queryFn: () => adminAPI.get(\"/admin/paystack/subaccounts\").then((r:any) => r.data.data||[]),\n  });\n\n  const stores = raw || [];\n\n  const rows = stores.map((s: any) => ({\n    store: (\n      <div style={{ display:\"flex\", alignItems:\"center\", gap:9 }}>\n        <div style={{ width:30, height:30, borderRadius:8, background:\"rgba(245,158,11,0.12)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", flexShrink:0 }}>\n          <Building2 size={13} color={V.amber}/>\n        </div>\n        <div>\n          <p style={{ fontSize:13, fontWeight:700, color:t.text, margin:0 }}>{s.name}</p>\n          <p style={{ fontSize:10, color:t.muted, margin:0 }}>/{s.slug}</p>\n        </div>\n      </div>\n    ),\n    owner:   <div><p style={{ fontSize:12, color:t.text, margin:0 }}>{s.owner?.name}</p><p style={{ fontSize:10, color:t.muted, margin:0 }}>{s.owner?.email}</p></div>,\n    code:    <code style={{ fontSize:11, color:V.amber, background:\"rgba(245,158,11,0.08)\", padding:\"2px 8px\", borderRadius:6 }}>{s.paystackSubaccountCode}</code>,\n    orders:  <span style={{ fontSize:13, fontWeight:700, color:t.text }}>{s._count?.orders||0}</span>,\n    link:    (\n      <a href={`https://dashboard.paystack.com/#/subaccounts`} target=\"_blank\" rel=\"noreferrer\"\n        style={{ padding:\"5px 8px\", borderRadius:7, background:\"rgba(245,158,11,0.08)\", border:\"1px solid rgba(245,158,11,0.15)\", color:V.amber, textDecoration:\"none\", display:\"flex\", alignItems:\"center\" }}>\n        <ExternalLink size={11}/>\n      </a>\n    ),\n  }));\n\n  return (\n    <div>\n      <PageHeader title=\"Paystack Subaccounts\" sub={`${stores.length} stores with active Paystack subaccounts`}/>\n\n      {stores.length === 0 && !isLoading ? (\n        <div style={{ padding:\"60px 0\", textAlign:\"center\" }}>\n          <Building2 size={32} style={{ color:t.muted, margin:\"0 auto 12px\" }}/>\n          <p style={{ fontSize:15, fontWeight:700, color:t.text, margin:\"0 0 6px\" }}>No subaccounts yet</p>\n          <p style={{ fontSize:13, color:t.muted }}>Once merchants verify their Paystack accounts, subaccounts will appear here.</p>\n        </div>\n      ) : (\n        <DataTable\n          loading={isLoading}\n          cols={[\n            { key:\"store\",  label:\"Store\",      width:\"2fr\"           },\n            { key:\"owner\",  label:\"Owner\",      width:\"1.5fr\", hide:\"sm\" },\n            { key:\"code\",   label:\"Sub. Code\",  width:\"1.5fr\"         },\n            { key:\"orders\", label:\"Orders\",     width:\"80px\",  hide:\"md\" },\n            { key:\"link\",   label:\"\",           width:\"40px\"          },\n          ]}\n          rows={rows}\n          empty=\"No subaccounts found\"\n        />\n      )}\n\n      <div style={{ marginTop:20, padding:\"16px 20px\", borderRadius:14, background:\"rgba(245,158,11,0.05)\", border:\"1px solid rgba(245,158,11,0.12)\" }}>\n        <p style={{ fontSize:12, color:\"rgba(245,158,11,0.7)\", margin:0, lineHeight:1.6 }}>\n          💡 Paystack subaccounts are created per merchant once their business account is verified. For direct management, visit <a href=\"https://dashboard.paystack.com\" target=\"_blank\" rel=\"noreferrer\" style={{ color:V.amber }}>dashboard.paystack.com</a>\n        </p>\n      </div>\n    </div>\n  );\n}\n","backend/src/controllers/admin.controller.ts":"// src/controllers/admin.controller.ts\nimport { Request, Response } from \"express\";\nimport { z } from \"zod\";\nimport prisma from \"../lib/prisma\";\nimport { AppError } from \"../utils/AppError\";\nimport { paginate, sanitizeUser } from \"../utils/helpers\";\nimport { AuthRequest } from \"../middleware/auth\";\nimport bcrypt from \"bcryptjs\";\n\n// ── Dashboard Stats ───────────────────────────────────────────────────────────\nexport const getDashboardStats = async (_req: AuthRequest, res: Response) => {\n  const [\n    totalUsers, activeUsers, suspendedUsers,\n    totalStores, activeStores,\n    totalOrders, totalRevenue, platformFees,\n    failedPayments, openTickets,\n    newUsersThisMonth, revenueThisMonth,\n  ] = await Promise.all([\n    await prisma.user.count({ where: { role: \"STORE_OWNER\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"ACTIVE\" } }),\n    await prisma.user.count({ where: { role: \"STORE_OWNER\", status: \"SUSPENDED\" } }),\n    await prisma.store.count(),\n    await prisma.store.count({ where: { status: \"ACTIVE\" } }),\n    await prisma.order.count(),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { amount: true } }),\n    await prisma.payment.aggregate({ where: { status: \"SUCCESS\" }, _sum: { platformFee: true } }),\n    await prisma.payment.count({ where: { status: \"FAILED\" } }),\n    await prisma.supportTicket.count({ where: { status: { in: [\"OPEN\",\"IN_PROGRESS\"] } } }),\n    await prisma.user.count({\n      where: {\n        role: \"STORE_OWNER\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n    }),\n    await prisma.payment.aggregate({\n      where: {\n        status: \"SUCCESS\",\n        createdAt: { gte: new Date(new Date().getFullYear(), new Date().getMonth(), 1) },\n      },\n      _sum: { amount: true },\n    }),\n  ]);\n\n  // Monthly revenue for last 7 months\n  const months = Array.from({ length: 7 }, (_, i) => {\n    const d = new Date();\n    d.setMonth(d.getMonth() - (6 - i));\n    return new Date(d.getFullYear(), d.getMonth(), 1);\n  });\n\n  const monthlyRevenue = await Promise.all(\n    months.map(async (start) => {\n      const end = new Date(start.getFullYear(), start.getMonth() + 1, 0);\n      const agg = await prisma.payment.aggregate({\n        where: { status: \"SUCCESS\", createdAt: { gte: start, lte: end } },\n        _sum:  { amount: true, platformFee: true },\n      });\n      return {\n        month:    start.toLocaleString(\"default\", { month: \"short\" }),\n        revenue:  agg._sum.amount || 0,\n        fees:     agg._sum.platformFee || 0,\n      };\n    })\n  );\n\n  // Gateway distribution\n  const gatewayStats = await prisma.payment.groupBy({\n    by:    [\"gateway\"],\n    where: { status: \"SUCCESS\" },\n    _sum:  { amount: true },\n    _count:{ id: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      users:         { total: totalUsers, active: activeUsers, suspended: suspendedUsers, newThisMonth: newUsersThisMonth },\n      stores:        { total: totalStores, active: activeStores },\n      orders:        { total: totalOrders },\n      revenue:       { total: totalRevenue._sum.amount || 0, thisMonth: revenueThisMonth._sum.amount || 0 },\n      platformFees:  { total: platformFees._sum.platformFee || 0 },\n      failedPayments,\n      openTickets,\n      monthlyRevenue,\n      gatewayStats,\n    },\n  });\n};\n\n// ── Get All Users ─────────────────────────────────────────────────────────────\nexport const getAllUsers = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, status, plan, search, role } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const where: any = {};\n  if (role)   where.role   = role;\n  if (status) where.status = status;\n  if (search) where.OR = [\n    { name:  { contains: search as string, mode: \"insensitive\" } },\n    { email: { contains: search as string, mode: \"insensitive\" } },\n  ];\n\n  if (plan) where.subscription = { plan };\n\n  const [users, total] = await Promise.all([\n    await prisma.user.findMany({\n      where, take, skip,\n      include: {\n        subscription: true,\n        stores: {\n          select: { id: true, name: true, status: true, _count: { select: { orders: true } } },\n        },\n        _count: { select: { stores: true, supportTickets: true } },\n      },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.user.count({ where }),\n  ]);\n\n  // Attach total revenue per user\n  const usersWithRevenue = await Promise.all(\n    users.map(async (user) => {\n      const revenue = await prisma.payment.aggregate({\n        where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n        _sum:  { amount: true, platformFee: true, storeEarnings: true },\n      });\n      return {\n        ...sanitizeUser(user),\n        revenue: {\n          total:         revenue._sum.amount || 0,\n          platformFees:  revenue._sum.platformFee || 0,\n          storeEarnings: revenue._sum.storeEarnings || 0,\n        },\n      };\n    })\n  );\n\n  return res.json({\n    success: true,\n    data: usersWithRevenue,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Get Single User (full detail) ─────────────────────────────────────────────\nexport const getUserDetail = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({\n    where: { id: userId },\n    include: {\n      subscription: true,\n      stores: {\n        include: {\n          _count:  { select: { products: true, orders: true, customers: true } },\n          payments:{ where: { status: \"SUCCESS\" }, select: { amount: true, platformFee: true, storeEarnings: true } },\n        },\n      },\n      supportTickets: { orderBy: { createdAt: \"desc\" }, take: 5 },\n      _count: { select: { stores: true, supportTickets: true } },\n    },\n  });\n  if (!user) throw new AppError(\"User not found\", 404);\n\n  const totalRevenue = await prisma.payment.aggregate({\n    where: { storeId: { in: user.stores.map((s) => s.id) }, status: \"SUCCESS\" },\n    _sum:  { amount: true, platformFee: true, storeEarnings: true },\n  });\n\n  return res.json({\n    success: true,\n    data: {\n      ...sanitizeUser(user),\n      totalRevenue: totalRevenue._sum.amount     || 0,\n      platformFees: totalRevenue._sum.platformFee|| 0,\n      payouts:      totalRevenue._sum.storeEarnings || 0,\n    },\n  });\n};\n\n// ── Update User ───────────────────────────────────────────────────────────────\nexport const updateUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    name:          z.string().min(2).optional(),\n    email:         z.string().email().optional(),\n    phone:         z.string().optional(),\n    status:        z.enum([\"ACTIVE\",\"SUSPENDED\",\"BANNED\"]).optional(),\n    emailVerified: z.boolean().optional(),\n    twoFAEnabled:  z.boolean().optional(),\n    adminNotes:    z.string().optional(),\n    flags:         z.array(z.string()).optional(),\n    country:       z.string().optional(),\n    city:          z.string().optional(),\n    role:          z.enum([\"STORE_OWNER\",\"SUPER_ADMIN\"]).optional(),\n  });\n\n  const data = schema.parse(req.body);\n  const user = await prisma.user.update({ where: { id: userId }, data });\n\n  // Audit log\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"User updated\", data: sanitizeUser(user) });\n};\n\n// ── Update Subscription ───────────────────────────────────────────────────────\nexport const updateUserSubscription = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const schema = z.object({\n    plan:            z.enum([\"STARTER\",\"PRO\",\"ADVANCED\"]),\n    status:          z.enum([\"ACTIVE\",\"CANCELLED\",\"EXPIRED\",\"PAST_DUE\"]).optional(),\n    currentPeriodEnd:z.string().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const sub = await prisma.subscription.update({\n    where: { userId },\n    data:  {\n      plan:   data.plan,\n      status: data.status,\n      ...(data.currentPeriodEnd && { currentPeriodEnd: new Date(data.currentPeriodEnd) }),\n    },\n    include: { user: { select: { email: true, name: true } } },\n  });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_SUBSCRIPTION\",\n      entity:   \"Subscription\",\n      entityId: userId,\n      newValues: data as any,\n    },\n  });\n\n  // Send subscription email\n  try {\n    const { emailService } = await import(\"../services/email.service\");\n    const u = (sub as any).user;\n    const endDate = sub.currentPeriodEnd?.toLocaleDateString(\"en-US\", { year: \"numeric\", month: \"long\", day: \"numeric\" }) || \"N/A\";\n    if (data.status === \"ACTIVE\" || (!data.status && sub.status === \"ACTIVE\")) {\n      emailService.sendSubscriptionStarted(u.email, u.name, data.plan, endDate);\n    } else if (data.status === \"CANCELLED\") {\n      emailService.sendSubscriptionCancelled(u.email, u.name, data.plan, endDate);\n    }\n  } catch {}\n\n  return res.json({ success: true, message: \"Subscription updated\", data: sub });\n};\n\n// ── Delete User ───────────────────────────────────────────────────────────────\nexport const deleteUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const user = await prisma.user.findUnique({ where: { id: userId } });\n  if (!user) throw new AppError(\"User not found\", 404);\n  if (user.role === \"SUPER_ADMIN\") throw new AppError(\"Cannot delete super admin\", 403);\n\n  await prisma.user.delete({ where: { id: userId } });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"DELETE_USER\",\n      entity:   \"User\",\n      entityId: userId,\n    },\n  });\n\n  return res.json({ success: true, message: \"User deleted\" });\n};\n\n// ── Platform Settings ─────────────────────────────────────────────────────────\nexport const getSettings = async (_req: AuthRequest, res: Response) => {\n  const settings = await prisma.platformSettings.findUnique({ where: { id: \"singleton\" } });\n  return res.json({ success: true, data: settings });\n};\n\nexport const updateSettings = async (req: AuthRequest, res: Response) => {\n  const schema = z.object({\n    platformFeePercent: z.number().min(0).max(50).optional(),\n    starterPrice:       z.number().optional(),\n    proPrice:           z.number().optional(),\n    advancedPrice:      z.number().optional(),\n    maintenanceMode:    z.boolean().optional(),\n    allowRegistration:  z.boolean().optional(),\n  });\n  const data = schema.parse(req.body);\n\n  const settings = await prisma.platformSettings.update({\n    where: { id: \"singleton\" },\n    data,\n  });\n\n  await (prisma.auditLog as any).create({\n    data: {\n      userId:   req.user!.userId,\n      action:   \"UPDATE_PLATFORM_SETTINGS\",\n      entity:   \"PlatformSettings\",\n      entityId: \"singleton\",\n      newValues: data as any,\n    },\n  });\n\n  return res.json({ success: true, message: \"Settings updated\", data: settings });\n};\n\n// ── Error Logs ────────────────────────────────────────────────────────────────\nexport const getErrorLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20, resolved } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  const where: any = {};\n  if (resolved !== undefined) where.resolved = resolved === \"true\";\n\n  const [logs, total] = await Promise.all([\n    await prisma.errorLog.findMany({ where, take, skip, orderBy: { createdAt: \"desc\" } }),\n    await prisma.errorLog.count({ where }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\nexport const resolveErrorLog = async (req: AuthRequest, res: Response) => {\n  const { logId } = req.params;\n  await prisma.errorLog.update({ where: { id: logId }, data: { resolved: true } });\n  return res.json({ success: true, message: \"Log resolved\" });\n};\n\n// ── Audit Logs ────────────────────────────────────────────────────────────────\nexport const getAuditLogs = async (req: AuthRequest, res: Response) => {\n  const { page = 1, limit = 20 } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n\n  const [logs, total] = await Promise.all([\n    await prisma.auditLog.findMany({\n      take, skip,\n      include: { user: { select: { name: true, email: true } } },\n      orderBy: { createdAt: \"desc\" },\n    }),\n    await prisma.auditLog.count(),\n  ]);\n\n  return res.json({\n    success: true,\n    data: logs,\n    pagination: { page: Number(page), limit: take, total, pages: Math.ceil(total / take) },\n  });\n};\n\n// ── Platform Analytics ────────────────────────────────────────────────────────\nexport const getPlatformAnalytics = async (req: AuthRequest, res: Response) => {\n  const { period = \"7d\" } = req.query;\n  const days = period === \"30d\" ? 30 : period === \"90d\" ? 90 : 7;\n  const from = new Date();\n  from.setDate(from.getDate() - days);\n\n  const [revenueByDay, ordersByDay, newUsersByDay] = await Promise.all([\n    prisma.payment.groupBy({\n      by: [\"createdAt\"],\n      where: { status: \"SUCCESS\", createdAt: { gte: from } },\n      _sum: { amount: true, platformFee: true },\n    }),\n    prisma.order.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from } },\n      _count: { id: true },\n    }),\n    prisma.user.groupBy({\n      by: [\"createdAt\"],\n      where: { createdAt: { gte: from }, role: \"STORE_OWNER\" },\n      _count: { id: true },\n    }),\n  ]);\n\n  return res.json({\n    success: true,\n    data: { revenueByDay, ordersByDay, newUsersByDay },\n  });\n};\n\n// ── Impersonation — login as any merchant ─────────────────────────────────────\nexport const impersonateUser = async (req: AuthRequest, res: Response) => {\n  const { userId } = req.params;\n  const admin = req.user!;\n  if (admin.role !== \"SUPER_ADMIN\") return res.status(403).json({ success:false, error:\"Forbidden\" });\n\n  const user = await prisma.user.findUnique({ where:{ id:userId }, include:{ stores:{ select:{ id:true, slug:true } } } });\n  if (!user) return res.status(404).json({ success:false, error:\"User not found\" });\n\n  // Log the impersonation\n  await prisma.auditLog.create({\n    data: { userId:admin.userId, action:\"IMPERSONATE\", resource:\"user\", resourceId:userId, details:{ targetEmail:user.email } } as any,\n  });\n\n  const { signAccessToken, setRefreshCookie } = await import(\"../config/jwt\");\n  const accessToken = signAccessToken({ userId:user.id, email:user.email, role:user.role as any, name:user.name||\"\" });\n  setRefreshCookie(res, signAccessToken({ userId:user.id, email:user.email, role:user.role as any, name:user.name||\"\" }));\n\n  return res.json({ success:true, message:`Now logged in as ${user.email}`, data:{ accessToken, user:{ id:user.id, email:user.email, name:user.name, role:user.role, stores:user.stores } } });\n};\n\n// ── Platform Coupons — create codes that work on any store ────────────────────\nexport const getPlatformCoupons = async (req: AuthRequest, res: Response) => {\n  const { page=1, limit=20 } = req.query;\n  const { take, skip } = paginate(Number(page), Number(limit));\n  // Platform coupons are stored in settings\n  const setting = await prisma.platformSetting.findUnique({ where:{ key:\"platform_coupons\" } });\n  const coupons = setting ? JSON.parse(setting.value) : [];\n  const paged   = coupons.slice(skip, skip+take);\n  return res.json({ success:true, data:paged, pagination:{ total:coupons.length, page:Number(page), limit:take, pages:Math.ceil(coupons.length/take) } });\n};\n\nexport const createPlatformCoupon = async (req: AuthRequest, res: Response) => {\n  const { code, type, value, maxUses, expiresAt, description, targetPlan } = req.body;\n  if (!code || !type || !value) return res.status(400).json({ success:false, error:\"code, type, value required\" });\n\n  const setting = await prisma.platformSetting.findUnique({ where:{ key:\"platform_coupons\" } });\n  const coupons = setting ? JSON.parse(setting.value) : [];\n\n  const existing = coupons.find((c:any) => c.code === code.toUpperCase());\n  if (existing) return res.status(400).json({ success:false, error:\"Code already exists\" });\n\n  const newCoupon = {\n    id: `pc_${Date.now()}`, code:code.toUpperCase(), type, value:Number(value),\n    maxUses:maxUses?Number(maxUses):null, expiresAt:expiresAt||null,\n    description:description||\"\", targetPlan:targetPlan||null,\n    usedCount:0, isActive:true, createdAt:new Date().toISOString(),\n  };\n\n  coupons.unshift(newCoupon);\n  await prisma.platformSetting.upsert({\n    where:{ key:\"platform_coupons\" },\n    update:{ value:JSON.stringify(coupons) },\n    create:{ key:\"platform_coupons\", value:JSON.stringify(coupons) },\n  });\n\n  await prisma.auditLog.create({\n    data:{ userId:req.user!.userId, action:\"CREATE\", resource:\"platform_coupon\", resourceId:newCoupon.id, details:newCoupon } as any,\n  });\n\n  return res.json({ success:true, message:\"Coupon created\", data:newCoupon });\n};\n\nexport const deletePlatformCoupon = async (req: AuthRequest, res: Response) => {\n  const { couponId } = req.params;\n  const setting = await prisma.platformSetting.findUnique({ where:{ key:\"platform_coupons\" } });\n  const coupons = setting ? JSON.parse(setting.value) : [];\n  const filtered = coupons.filter((c:any) => c.id !== couponId);\n  await prisma.platformSetting.update({ where:{ key:\"platform_coupons\" }, data:{ value:JSON.stringify(filtered) } });\n  return res.json({ success:true, message:\"Coupon deleted\" });\n};\n\n// ── Email Templates ────────────────────────────────────────────────────────────\nexport const getEmailTemplates = async (_req: AuthRequest, res: Response) => {\n  const setting = await prisma.platformSetting.findUnique({ where:{ key:\"email_templates\" } });\n  const defaults = {\n    welcome:       { subject:\"Welcome to DropOS! 🚀\", body:\"Hi {{name}},\\n\\nWelcome to DropOS! Your store {{storeName}} is ready.\\n\\nStart by adding your first product or ask KIRO to set up your store for you.\\n\\n{{ctaUrl}}\\n\\nThe DropOS Team\" },\n    orderConfirm:  { subject:\"Order #{{orderNumber}} confirmed ✅\", body:\"Hi {{customerName}},\\n\\nYour order from {{storeName}} has been confirmed.\\n\\nOrder: #{{orderNumber}}\\nTotal: {{total}}\\nEstimated delivery: {{deliveryDate}}\\n\\nTrack your order: {{trackingUrl}}\" },\n    orderShipped:  { subject:\"Your order is on its way! 📦\", body:\"Hi {{customerName}},\\n\\nGreat news! Your order #{{orderNumber}} from {{storeName}} has been shipped.\\n\\nTrack it here: {{trackingUrl}}\" },\n    passwordReset: { subject:\"Reset your DropOS password\", body:\"Hi {{name}},\\n\\nClick the link below to reset your password. This link expires in 1 hour.\\n\\n{{resetUrl}}\\n\\nIf you didn't request this, ignore this email.\" },\n    planUpgraded:  { subject:\"You're now on {{plan}} 🎉\", body:\"Hi {{name}},\\n\\nYour DropOS plan has been upgraded to {{plan}}. KIRO is now fully unlocked.\\n\\nExplore your new features: {{dashboardUrl}}\" },\n  };\n  const templates = setting ? { ...defaults, ...JSON.parse(setting.value) } : defaults;\n  return res.json({ success:true, data:templates });\n};\n\nexport const updateEmailTemplate = async (req: AuthRequest, res: Response) => {\n  const { key, subject, body } = req.body;\n  if (!key || !subject || !body) return res.status(400).json({ success:false, error:\"key, subject, body required\" });\n\n  const setting = await prisma.platformSetting.findUnique({ where:{ key:\"email_templates\" } });\n  const templates = setting ? JSON.parse(setting.value) : {};\n  templates[key] = { subject, body };\n\n  await prisma.platformSetting.upsert({\n    where:{ key:\"email_templates\" },\n    update:{ value:JSON.stringify(templates) },\n    create:{ key:\"email_templates\", value:JSON.stringify(templates) },\n  });\n\n  return res.json({ success:true, message:\"Template saved\" });\n};\n\n// ── Churn Analysis ─────────────────────────────────────────────────────────────\nexport const getChurnAnalysis = async (_req: AuthRequest, res: Response) => {\n  const thirtyDaysAgo = new Date(); thirtyDaysAgo.setDate(thirtyDaysAgo.getDate()-30);\n  const sixtyDaysAgo  = new Date(); sixtyDaysAgo.setDate(sixtyDaysAgo.getDate()-60);\n\n  const [\n    churned,         // Paid plan → suspended/no activity\n    atRisk,          // No orders in 14 days\n    recentCancels,   // Downgraded to free in last 30 days\n    avgLifetime,\n  ] = await Promise.all([\n    prisma.user.count({ where:{ role:\"STORE_OWNER\", status:\"SUSPENDED\", updatedAt:{ gte:thirtyDaysAgo } } }),\n    prisma.store.count({ where:{ status:\"ACTIVE\", orders:{ none:{ createdAt:{ gte:thirtyDaysAgo } } } } }),\n    prisma.user.count({ where:{ role:\"STORE_OWNER\", plan:\"FREE\", updatedAt:{ gte:thirtyDaysAgo } } }),\n    prisma.user.aggregate({ where:{ role:\"STORE_OWNER\" }, _avg:{ id:true } }), // placeholder\n  ]);\n\n  // Monthly churn for last 6 months\n  const months = Array.from({ length:6 }, (_,i) => {\n    const d = new Date(); d.setMonth(d.getMonth()-(5-i)); return new Date(d.getFullYear(),d.getMonth(),1);\n  });\n\n  const monthlyChurn = await Promise.all(months.map(async (start) => {\n    const end = new Date(start.getFullYear(), start.getMonth()+1, 0);\n    const count = await prisma.user.count({ where:{ role:\"STORE_OWNER\", status:\"SUSPENDED\", updatedAt:{ gte:start, lte:end } } });\n    return { month:start.toLocaleString(\"default\",{ month:\"short\" }), churned:count };\n  }));\n\n  return res.json({ success:true, data:{ churned, atRisk, recentCancels, monthlyChurn, churnRate:Math.round((churned/Math.max(await prisma.user.count({ where:{ role:\"STORE_OWNER\" } }),1))*100) } });\n};\n\n// ── Growth Metrics — MRR, ARR, LTV ────────────────────────────────────────────\nexport const getGrowthMetrics = async (_req: AuthRequest, res: Response) => {\n  const now = new Date();\n  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);\n\n  const [totalUsers, paidUsers, monthRevenue, allRevenue] = await Promise.all([\n    prisma.user.count({ where:{ role:\"STORE_OWNER\" } }),\n    prisma.user.count({ where:{ role:\"STORE_OWNER\", plan:{ not:\"FREE\" } } }),\n    prisma.payment.aggregate({ where:{ status:\"SUCCESS\", createdAt:{ gte:monthStart } }, _sum:{ platformFee:true } }),\n    prisma.payment.aggregate({ where:{ status:\"SUCCESS\" }, _sum:{ platformFee:true } }),\n  ]);\n\n  const MRR = monthRevenue._sum.platformFee || 0;\n  const ARR = MRR * 12;\n  const LTV = totalUsers > 0 ? (allRevenue._sum.platformFee||0) / totalUsers : 0;\n  const ARPU = paidUsers > 0 ? MRR / paidUsers : 0;\n  const convRate = totalUsers > 0 ? Math.round((paidUsers/totalUsers)*100) : 0;\n\n  // Weekly growth (last 8 weeks)\n  const weeklyGrowth = await Promise.all(Array.from({length:8},(_,i)=>{\n    const end = new Date(); end.setDate(end.getDate()-(7*(7-i)));\n    const start = new Date(end); start.setDate(start.getDate()-7);\n    return prisma.user.count({ where:{ role:\"STORE_OWNER\", createdAt:{ gte:start, lte:end } } })\n      .then(count => ({ week:`W${i+1}`, newUsers:count }));\n  }));\n\n  return res.json({ success:true, data:{ MRR, ARR, LTV, ARPU, convRate, totalUsers, paidUsers, weeklyGrowth } });\n};\n\n// ── Paystack Subaccounts ───────────────────────────────────────────────────────\nexport const getPaystackSubaccounts = async (_req: AuthRequest, res: Response) => {\n  const stores = await prisma.store.findMany({\n    where:{ paystackSubaccountCode:{ not:null } },\n    select:{ id:true, name:true, slug:true, paystackSubaccountCode:true, owner:{ select:{ name:true, email:true } }, _count:{ select:{ orders:true } } },\n    take:50,\n  });\n  return res.json({ success:true, data:stores });\n};\n","backend/src/routes/admin.routes.ts":"import { Router } from \"express\";\nimport { authenticate } from \"../middleware/auth\";\nimport {\n  getDashboardStats, getAllUsers, getUserDetail,\n  updateUser, updateUserSubscription, deleteUser,\n  getSettings, updateSettings,\n  getErrorLogs, resolveErrorLog,\n  getAuditLogs, getPlatformAnalytics,\n  // New features\n  getAllStores, updateStore,\n  getAllOrders, getAllPayments,\n  broadcastMessage, changeUserPlan,\n  getFeatureFlags, updateFeatureFlag,\n  impersonateUser,\n  getPlatformCoupons, createPlatformCoupon, deletePlatformCoupon,\n  getEmailTemplates, updateEmailTemplate,\n  getChurnAnalysis,\n  getGrowthMetrics,\n  getPaystackSubaccounts,\n} from \"../controllers/admin.controller\";\n\nconst router = Router();\nrouter.use(authenticate);\n\n// Overview\nrouter.get (\"/dashboard\",                    getDashboardStats);\nrouter.get (\"/stats\",                        getDashboardStats);\nrouter.get (\"/analytics\",                    getPlatformAnalytics);\n\n// Users\nrouter.get   (\"/users\",                      getAllUsers);\nrouter.get   (\"/users/:userId\",              getUserDetail);\nrouter.patch (\"/users/:userId\",              updateUser);\nrouter.patch (\"/users/:userId/subscription\", updateUserSubscription);\nrouter.patch (\"/users/:userId/plan\",         changeUserPlan);\nrouter.post  (\"/users/:userId/impersonate\",  impersonateUser);\nrouter.delete(\"/users/:userId\",              deleteUser);\n\n// Stores\nrouter.get   (\"/stores\",                     getAllStores);\nrouter.patch (\"/stores/:storeId\",            updateStore);\n\n// Orders & Payments\nrouter.get (\"/orders\",                       getAllOrders);\nrouter.get (\"/payments\",                     getAllPayments);\nrouter.get (\"/paystack/subaccounts\",         getPaystackSubaccounts);\n\n// Growth & Churn\nrouter.get (\"/growth\",                       getGrowthMetrics);\nrouter.get (\"/churn\",                        getChurnAnalysis);\n\n// Platform Tools\nrouter.post  (\"/broadcast\",                  broadcastMessage);\nrouter.get   (\"/feature-flags\",              getFeatureFlags);\nrouter.patch (\"/feature-flags\",              updateFeatureFlag);\n\n// Platform Coupons\nrouter.get   (\"/coupons\",                    getPlatformCoupons);\nrouter.post  (\"/coupons\",                    createPlatformCoupon);\nrouter.delete(\"/coupons/:couponId\",          deletePlatformCoupon);\n\n// Email Templates\nrouter.get   (\"/email-templates\",            getEmailTemplates);\nrouter.patch (\"/email-templates\",            updateEmailTemplate);\n\n// Settings & Logs\nrouter.get   (\"/settings\",                   getSettings);\nrouter.patch (\"/settings\",                   updateSettings);\nrouter.get   (\"/error-logs\",                 getErrorLogs);\nrouter.patch (\"/error-logs/:logId/resolve\",  resolveErrorLog);\nrouter.get   (\"/audit-logs\",                 getAuditLogs);\n\nexport default router;\n"};
